(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-nvfp4-hybrid-dit"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-1\">一 · 一次色彩漂移事故：为什么“全 FP4”在 DiT 上不成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-2\">二 · 误差从哪里来：两级 micro-block scaling 与 outlier 的算术</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-3\">三 · 分层分派的数据流：从层标签到 BF16 汇合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-4\">四 · 适用边界的量化刻画：敏感层比例决定收益上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-5\">五 · 失败模式与工程判断：三条硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-6\">六 · 失效边界：从一次“全量化”线上事故说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-7\">七 · 离线敏感度画像：kurtosis 与 max/mean 比如何变成层标签</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-8\">八 · 权重量化与 block scale 落盘：两级缩放的存储布局</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-9\">九 · 推理时按层标签分派：两条 GEMM 队列与调度碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-10\">十 · 反量化汇合与 BF16 残差：精度断层的接缝处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-11\">十一 · 回到 BF16 与 VAE 边界：解码器输入不能有精度断层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-12\">十二 · 端到端代价核算：每一步落在延迟、吞吐还是显存上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-13\">十三 · 分派粒度与融合边界：混合精度在真实链路里会在哪里失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-14\">十四 · 两级缩放的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-15\">十五 · 误差上界的来源与敏感层判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-16\">十六 · 加速比的代数结构与 α 的含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-17\">十七 · 分派与汇合的伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-18\">十八 · 融合 kernel 的碎片化代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-19\">十九 · 失效边界：敏感层比例、分布外激活与分支碎片化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-20\">二十 · 请求形态：单步前向的批量 latent 才是主战场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-21\">二十一 · 长度分布：分辨率与序列长度决定批的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-22\">二十二 · 并发与批大小：连续批处理在扩散服务里的变形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-23\">二十三 · 负载不对时：三类可观测的退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-24\">二十四 · 配方落地：把负载条件写进部署参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-25\">二十五 · 负载配方：批大小、长度分布与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-26\">二十六 · 硬件档位与并行拓扑的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-27\">二十七 · 量化方案的落地形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-28\">二十八 · 中间激活缓存（KV 策略）的容量换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-29\">二十九 · 调度参数与 kernel 碎片化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-30\">三十 · 一个可复现的配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-31\">三十一 · 配方边界：敏感层比例决定收益上限，融合 kernel 决定收益下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-32\">三十二 · 显存账：权重、激活与中间缓存的四倍差从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-33\">三十三 · 带宽与反量化：block scale 的读取代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-34\">三十四 · 通信：张量并行下的精度域对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-35\">三十五 · 功耗与尾延迟：批大小与 SLO 的夹缝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-36\">三十六 · 规模上限：敏感层比例与碎片化的双重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-37\">三十七 · 混合精度 DiT 的规模边界：先崩在调度，再崩在显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-38\">三十八 · 精度崩坏的三种指纹与定位手段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-39\">三十九 · OOM 的三条来源与显存核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-40\">四十 · 批抖动与路由不均：调度层的两类病</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-41\">四十一 · 尾延迟尖刺的四个来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-42\">四十二 · 监控指标体系与告警阈值设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-43\">四十三 · 回滚路径的分级与切换成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-44\">四十四 · 失效边界：从“能跑”到“崩坏”只差一次误判</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-45\">四十五 · 对照轴：把“选哪个”拆成四个可判定的维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-46\">四十六 · 决策表：五种候选与适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-47\">四十七 · 收益上界的算术：什么时候 NVFP4 值得选</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-48\">四十八 · 与 MX 及 FP8 的分界：精度档位数量决定调优成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-49\">四十九 · 适用条件清单与规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-hybrid-dit-sec-50\">五十 · 与 FP8、MX 两条相邻路线的分岔口：何时值得为 NVFP4 付融合 kernel 的账</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:528px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 528.3 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">离线分析各层激活的 kurtosis 与 max/mean 比，标记高敏感层</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">高敏感层权重与激活保持 FP8，其余层权重量化为 NVFP4 并存储 bl…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理时 latent 进入 DiT，按层标签分派到 FP4 或 FP8 G…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">FP4 GEMM 输出经 block scale 反量化后与 FP8 分支…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">VAE 解码前统一回到 BF16，避免解码器输入精度断层</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-1\">一 · 一次色彩漂移事故：为什么“全 FP4”在 DiT 上不成立</h3>\n<p>某条面向 1024×1024 分辨率、以单图端到端时延为 SLO 的服务链路上，工程团队把 DiT 主体 GEMM 一次性压到 NVFP4，权重与激活同走 E2M1，VAE 解码前也没有做精度回切。上线后第一批请求的时延确实下来了，但抽检图像出现两类稳定复现的异常：一类是整体色偏，画面像蒙了一层偏青的雾；另一类是结构崩坏，主体轮廓在采样中后段突然塌陷成块状纹理。回滚到 FP8 后异常消失，说明问题不在采样器也不在调度器，而在数值路径。</p>\n<p>定位过程按数据流倒推。第一处断点在 VAE 解码器入口：DiT 输出 latent 以低精度直接喂给解码器，解码器第一层卷积的输入动态范围与训练时不一致，色彩通道的偏置被系统性放大，形成色偏。第二处断点在 DiT 内部：timestep embedding 经 MLP 后的激活存在显著 outlier，attention 输出投影的通道同样如此，这些通道在 E2M1 的 4bit 尾数下被压到相邻量化格点，条件信息与注意力残差同时失真，采样轨迹在中后段偏离，表现为结构崩坏。事故的本质不是“FP4 不能用”，而是“把 outlier 敏感层和普通线性层放进同一个精度档位”。</p>\n<p>这个失败案例划出了本算法要解决的问题边界：它解决的是 DiT 权重与激活在 4bit 下量化误差急剧放大、尤其 timestep embedding 与 attention 输出通道存在显著 outlier、直接 FP4 全量化导致结构崩坏的问题，手段是在 Blackwell NVFP4 上做分层混合精度。它不解决采样步数、调度器设计、CFG 合并策略、特征缓存跳步这些算法层问题，也不解决 VAE 自身的分块并行解码效率；那些属于相邻条目。它同样不承诺“任意模型开箱即用”，因为层敏感度依赖离线校准集。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-2\">二 · 误差从哪里来：两级 micro-block scaling 与 outlier 的算术</h3>\n<p>NVFP4 的权重量化写成两级缩放：</p>\n<div class=\"formula\">$$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}},\\qquad \\hat{w}_i\\in\\text{E2M1}$$</div>\n<p>其中 $\\hat{w}_i$ 是 4bit 尾数，$s_{\\text{block}}$ 是块级缩放，$s_{\\text{tensor}}$ 是张量级缩放。单级缩放的问题在于：一个张量内若存在少数极大值通道，张量级缩放会被这些 outlier 拉大，导致其余正常通道的量化步长同步变粗，有效位数被浪费。块级缩放把张量切成 micro-block，每块独立定标，outlier 只污染自己所在的块。两级缩放把 E2M1 有限的动态范围拉回可用区间，这是 NVFP4 能在 Blackwell 原生 FP4 Tensor Core 与 block scale 硬件路径上跑起来的前提。</p>\n<p>误差的量级可以用一个比例刻画：</p>\n<div class=\"formula\">$$\\text{err}_{\\ell}\\propto \\frac{\\max|a_\\ell|}{\\text{rms}(a_\\ell)}$$</div>\n<p>该比值越大，说明该层激活的分布越“尖”，少数通道主导了动态范围，量化信噪比越差。timestep embedding 的 MLP 与 attention 输出投影正是这类层：条件信号经过非线性后被少数通道放大，max/rms 比显著高于普通 FFN 线性层。离线阶段分析各层激活的 kurtosis 与 max/mean 比，就是在给这个比值排序，把高敏感层标记出来。</p>\n<p>系统代价直接体现在三个维度。显存上，NVFP4 权重为 BF16 的 1/4，中间激活缓存（KV 指这里的中间激活缓存）低精度化后显存大幅下降，可容纳更大 batch 或更高分辨率；吞吐上，NVFP4 在 Blackwell 上吞吐为 FP8 的 2 倍，主体 GEMM 可再降一半时延；但这一切以“敏感层被隔离”为条件，一旦 outlier 层被误压，收益被画质退化抵消。举例：同一张 1024×1024 latent，若 timestep MLP 走 FP4，条件嵌入的通道误差会在每一层 attention 的调制中被复利放大，单步误差不大，二十步采样后累积成可见的结构偏移。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-3\">三 · 分层分派的数据流：从层标签到 BF16 汇合点</h3>\n<p>机制按数据流顺序展开。离线阶段：在校准集上跑前向，统计每层激活的 kurtosis 与 max/mean 比，标记高敏感层，产出层标签表。这一步的产物不是权重本身，而是一张“哪些层走 FP8、哪些层走 NVFP4”的路由表。高敏感层权重与激活保持 FP8，其余层权重量化为 NVFP4 并存储 block scale。推理阶段：latent 进入 DiT，按层标签分派到 FP4 或 FP8 GEMM 队列；FP4 GEMM 输出经 block scale 反量化后，与 FP8 分支结果在 BF16 残差处汇合；VAE 解码前统一回到 BF16，避免解码器输入精度断层。</p>\n<p>用伪代码思路描述单步前向的分派逻辑：对每个线性层 $\\ell$，若 $\\text{tag}(\\ell)=\\text{FP8}$，走 FP8 GEMM 并保持 FP8 累加输出；否则走 NVFP4 GEMM，输出乘以 $s_{\\text{block}}\\cdot s_{\\text{tensor}}$ 反量化到 BF16；两条分支的结果在残差加法处统一为 BF16 后再进入下一子层。关键在于汇合点必须是 BF16 而非 FP8，否则残差流会在不同精度间来回截断，误差不可控。</p>\n<p>代价是工程链路变长。层敏感度分析需要离线校准集，换模型或换分辨率要重跑，这意味着每上一个新分辨率档位就多一轮校准与验证。更棘手的是 kernel 调度碎片化：FP4 与 FP8 分支混跑，同一层序列里交替出现两种 GEMM，GPU 上的 kernel launch 与队列切换开销吃掉一部分理论吞吐，需手写融合 kernel 才能兑现 NVFP4 相对 FP8 的 2 倍吞吐。举例：一个 batch 为 1–8 的批量 latent 请求，若不做融合，分派边界处的同步与反量化会插入额外延迟，单图端到端时延的收益从“主体 GEMM 减半”缩水到远低于此；做了融合后，反量化被折进 GEMM 的 epilogue，残差汇合在同一 kernel 内完成，碎片化才被压住。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-4\">四 · 适用边界的量化刻画：敏感层比例决定收益上限</h3>\n<p>收益可以用一个粗粒度的加速比模型估计：</p>\n<div class=\"formula\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</div>\n<p>$\\alpha_{\\text{fp4}}$ 是走 NVFP4 的计算占比，$1-\\alpha_{\\text{fp8}}$ 是走 FP8 的占比，0.5 对应 FP4 相对 FP8 的时延减半。这个式子说明一件事：敏感层越多，$\\alpha_{\\text{fp4}}$ 越小，加速比越趋近于 1，分层混合精度的收益被稀释。规模上限因此受 outlier 层比例与 kernel 碎片化双重约束。若某模型的 timestep MLP 与 attention 输出投影占主体 GEMM 的比例很高，把这两类层全部保 FP8 后，剩下的 NVFP4 面积不足以支撑“再降一半时延”的预期。</p>\n<p>适用场景可以收敛为三条判断。其一，显存紧张：权重降至 BF16 的 1/4、中间激活缓存大幅下降，使更大 batch 或更高分辨率成为可能，这是最确定的收益。其二，主体 GEMM 占主导：若端到端时延里 GEMM 占比高，NVFP4 的 2 倍吞吐才有意义；若时延被 VAE 解码或调度开销主导，压 GEMM 的边际收益有限。其三，能承担离线校准与 kernel 调优成本：校准集、层标签表、融合 kernel 都是持续维护项，服务化场景下这是可摊销的固定成本，研究性一次性任务则未必划算。</p>\n<p>不适用的情况同样明确。分布外提示可能让被判低敏感层的误差放大——校准集覆盖不到的输入分布会改变激活的 max/rms 比，原本安全的层可能临时变成高敏感层，而路由表是静态的，不会自适应。这类风险在开放域文生图服务里是常态，需要在上线前用多分布校准集覆盖，或保留一条可回切的 FP8 全量路径作为兜底。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-5\">五 · 失败模式与工程判断：三条硬约束</h3>\n<p>第一条硬约束是融合 kernel。FP4 与 FP8 分支未手写融合 kernel 时，调度碎片化使实际吞吐远低于理论值，这是最常见的“纸面 2 倍、实测打折”来源。判断标准不是看 GEMM 单算子吞吐，而是看单步前向里分派边界的同步次数与反量化的插入位置；反量化必须在 epilogue 内完成，残差汇合必须与 GEMM 同 kernel。</p>\n<p>第二条硬约束是校准的时效性。换模型或换分辨率未重跑层敏感度分析，outlier 层被误压到 NVFP4，直接导致结构崩坏。分辨率变化会改变 latent 的空间统计，进而改变 attention 输出通道的分布，旧路由表失效。工程上应把“分辨率档位”作为校准的键，而不是把路由表当作模型级常量。</p>\n<p>第三条硬约束是解码前的精度回切。VAE 解码前未统一回 BF16，解码器输入精度断层引起色彩漂移与细节丢失，这正是开篇事故的第一处断点。这条约束的成本极低——一次精度转换——但漏掉它的代价是整条链路的画质验收不通过，属于典型的“低成本高杠杆”检查项。</p>\n<p>把三条约束合起来看，本算法的工程判断可以落在一句话上：NVFP4 混合精度的收益不是来自“用了 4bit”，而是来自“把 outlier 层从 4bit 里摘出去，并让剩下的 4bit 路径不被调度碎片吃掉”。敏感层比例决定上限，融合 kernel 决定能否触到上限，校准与回切决定会不会跌破下限。三者中任何一项缺失，事故形态就会从时延不达标滑向画质崩坏，而后者在服务化场景里更难被自动监控捕获。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-6\">六 · 失效边界：从一次“全量化”线上事故说起</h3>\n<p>某服务化 DiT 出图集群把整网权重与激活一次性压到 NVFP4，离线校准集上 FID 尚可，上线后却收到成批投诉：高分辨率、长提示词请求的画面出现网格状结构崩坏与色块，而低分辨率短提示词基本正常。复盘定位到两处：timestep embedding 的 MLP 与 attention 输出投影的激活通道存在显著 outlier，其 max/mean 比远高于其余层，E2M1 的 4bit 尾数在两级 micro-block scaling 下仍被这些通道拉爆动态范围，误差沿残差主干逐层放大；同时 VAE 解码前未统一回 BF16，解码器输入出现精度断层，色彩漂移与细节丢失叠加在结构崩坏之上。事故的本质不是“FP4 不能用”，而是把敏感层与不敏感层放进同一个精度档位。</p>\n<p>该方案解决的问题因此有明确边界：它只处理“主体 GEMM 占主导、显存紧张、且能承担离线校准”的 DiT 单步前向批量 latent 生成，批大小按显存与 SLO 取 1–8，SLO 以单图端到端时延计。它不解决注意力本身的算法开销、不解决 VAE 解码器的算力瓶颈、也不解决分布外提示带来的激活漂移——后者恰恰是失效条件：层敏感度分析依赖校准集，换模型或换分辨率必须重跑，否则被判低敏感的层在分布外输入上误差放大，等于把事故重演一遍。敏感层比例是收益的硬上限，敏感层越多，FP4 覆盖的 GEMM 越少，理论上的 2 倍吞吐与 1/4 显存就越难兑现。</p>\n<p>系统代价集中在工程链路而非单点算子。分层后 FP4 与 FP8 两条 GEMM 队列混跑，kernel 调度碎片化，若不手写融合 kernel，实际吞吐远低于理论值；融合 kernel 要把 block scale 反量化、BF16 残差汇合与层标签分派压进同一流水，否则每次分支切换都是一次启动开销。可用一个粗略上界判断收益是否成立：</p>\n<div class=\"formula\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</div>\n<p>其中 $\\alpha_{\\text{fp4}}$ 为走 NVFP4 的 GEMM 时间占比，$1-\\alpha_{\\text{fp8}}$ 为保留 FP8/BF16 的部分；只有当 $\\alpha_{\\text{fp4}}$ 足够高、且融合 kernel 把调度开销压住时，整体时延才接近减半。判断是否适用，先看敏感层占比与分辨率切换频率：分辨率频繁变动、校准集覆盖不足、又无力维护融合 kernel 的团队，应退回纯 FP8 方案，把 NVFP4 留给稳定分辨率、主体 GEMM 主导的服务化场景。</p>\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-7\">七 · 离线敏感度画像：kurtosis 与 max/mean 比如何变成层标签</h3>\n<p>混合精度的第一步不在 GPU 上，而在校准集上。给定一批代表性 latent 与 timestep 采样点，对每一层线性层的输入激活 $a_\\ell$ 统计两个统计量：峰度 $\\text{kurt}(a_\\ell)=\\mathbb{E}[(a-\\mu)^4]/\\sigma^4$，以及动态范围比 $\\text{err}_{\\ell}\\propto \\max|a_\\ell|/\\text{rms}(a_\\ell)$。前者刻画分布拖尾的厚重程度，后者直接对应 E2M1 只有 4 个尾数位时被单个极端值吃掉的量化台阶数。两个量都高的层——典型是 timestep embedding 的 MLP 与 attention 输出投影——被标记为高敏感层，其余层标记为 FP4 候选。这一步的输入是校准集张量，输出是一张逐层标签表（层名 → {FP8, NVFP4}）外加每层的 block scale 初值，代价是离线一次性算力与工程时间：换模型、换分辨率、换 latent 通道数都要重跑，因为激活分布随分辨率和 patch 尺寸漂移。工程上把这张表做成可版本化的 JSON 随模型一起发布，推理侧只读不重算，避免在线校准污染 SLO。</p>\n<p>敏感度判定的一个具体例子：某 DiT 的 timestep MLP 第一层在 $t$ 接近采样末端时激活 max/rms 比可达数十量级，若强行压到 E2M1，单个 outlier 会把整块的 $s_{\\text{block}}$ 抬高，导致同块内其余权重全部落到最低几个量化台阶上，等效于把该层打成稀疏噪声。这类层保留 FP8 后，误差不再由 4bit 尾数主导，而是由 FP8 的 E4M3 动态范围吸收。代价是这些层仍占 FP8 的带宽与算力，因此 FP4 收益上限被敏感层比例直接压缩：敏感层越多，$\\alpha_{\\text{fp4}}$（走 FP4 的 GEMM 时间占比）越小，整体加速越接近 1。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-8\">八 · 权重量化与 block scale 落盘：两级缩放的存储布局</h3>\n<p>对判为 FP4 的层，权重按两级 micro-block scaling 量化：</p>\n<div class=\"formula\">$$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}},\\qquad \\hat{w}_i\\in\\text{E2M1}$$</div>\n<p>其中 $\\hat{w}_i$ 是 4bit 尾数，$s_{\\text{block}}$ 是块级缩放（典型为每 16 或 32 个元素一块），$s_{\\text{tensor}}$ 是张量级缩放。两级缩放的意义在于把 E2M1 极窄的动态范围拉回可用区间：块级缩放吸收块内局部幅度差异，张量级缩放吸收跨通道的整体偏移，二者相乘后单个 4bit 码点所代表的实数值才落在权重真实分布上。落盘格式因此不是纯 4bit 张量，而是「4bit 权重 + 每块一个 FP8 scale + 每张量一个 FP32 scale」的打包结构，显存占用约为 BF16 的 1/4 再加 scale 开销（scale 占比随块大小增大而下降）。这一步的输入是 BF16 权重与校准得到的 scale，输出是可直接喂给 Blackwell FP4 Tensor Core 的打包缓冲；代价发生在加载期而非推理期，但打包布局必须与 kernel 的读取顺序对齐，否则反量化会退化成逐元素标量操作，把 2 倍吞吐吃掉。</p>\n<p>高敏感层在这一步走另一条路：权重与激活都保持 FP8，不进入两级缩放路径，只做常规 per-tensor 或 per-channel scale。于是模型在显存里是两种格式并存的混合体，加载器需要按层标签选择解析器。工程判断：把 FP4 层的块大小选大可以省 scale 带宽，但块内幅度差异变大后 $s_{\\text{block}}$ 被 outlier 抬高的问题会回来，因此块大小要与敏感度分析联合调，而不是独立超参。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-9\">九 · 推理时按层标签分派：两条 GEMM 队列与调度碎片</h3>\n<p>latent 进入 DiT 后，前向按层序遍历，每到一个线性层就查标签表：FP4 层把激活也量化到 E2M1 并附上块 scale，投递到 FP4 GEMM 队列；FP8 层投递到 FP8 GEMM 队列。两条队列在时间上交错，因为 DiT 的层是串行依赖的，FP4 与 FP8 分支不能真正并行，只能背靠背发射。这一步的输入是 BF16 latent 与当前 timestep 嵌入，输出是每层 GEMM 的结果张量；代价的核心不是算力而是调度：两种 kernel 的 tile 形状、共享内存占用、warpgroup 配置不同，切换时存在流水线气泡，且小 batch（1–8）下每个 GEMM 的 M 维很窄，tile 利用率本就偏低，切换开销占比被放大。理论 2 倍吞吐要在 $\\alpha_{\\text{fp4}}$ 高、切换次数少、且 kernel 融合的前提下才兑现。</p>\n<p>伪代码思路：</p>\n<ul>\n<li>for layer in dit.layers: tag = label[layer]; if tag == FP4: x_q, s = quant_nvfp4(x); y = gemm_fp4(x_q, w_q4, s_w, s_x); else: x_q8 = quant_fp8(x); y = gemm_fp8(x_q8, w_q8); x = y + residual(x)</li>\n</ul>\n<p>加速比的粗略表达为</p>\n<div class=\"formula\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</div>\n<p>它说明 FP4 占比越高、FP8 分支越少，越接近 2 倍；反之敏感层多则迅速回落。具体例子：一个 24 层 DiT 若只有 6 层被判高敏感，$\\alpha_{\\text{fp4}}$ 约 0.75，理论加速上限约 1.6 倍，而实际因切换气泡可能只拿到更低的兑现率——这正是必须手写融合 kernel 的动机：把相邻的 FP4/FP8 层在同一个 persistent kernel 内串起来，用统一 tile 调度消掉队列切换。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-10\">十 · 反量化汇合与 BF16 残差：精度断层的接缝处</h3>\n<p>FP4 GEMM 的输出是 INT32 累加结果加块 scale，必须经反量化回到高精度才能与 FP8 分支结果相加。汇合点选在 BF16 残差处：FP4 分支输出乘 $s_{\\text{block}}\\cdot s_{\\text{tensor}}$ 还原，FP8 分支输出按自身 scale 还原，两者在 BF16 精度下做残差加法，再进入下一层或归一化。这一步的输入是两条分支的低精度输出与各自的 scale，输出是 BF16 激活；代价是反量化本身的带宽与指令开销——每个输出元素都要读 scale、做乘法，若 scale 布局与输出 tile 不对齐，反量化会成为新的瓶颈，尤其在小 M 下算力利用率低时更明显。把汇合点放在残差而非 GEMM 内部，是为了让两条分支各自保持原生 Tensor Core 路径，避免在累加器里混精度导致硬件路径退化。</p>\n<p>具体机制细节：FP4 的块级 scale 在反量化时按块广播，若一个输出 tile 跨越多个输入块，需要按 K 维分段乘不同 scale 再累加，这要求 kernel 在 epilogue 里做分段归约而不是一次性乘。工程上常把这一步与残差加法、LayerNorm 融合进同一个 epilogue，减少一次激活的往返显存。代价判断：融合 epilogue 能省带宽但增加寄存器压力，在 batch 1–8 的窄 M 场景下寄存器才是稀缺资源，融合深度要按占用率实测决定，不能照搬大 M 训练 kernel 的配置。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-11\">十一 · 回到 BF16 与 VAE 边界：解码器输入不能有精度断层</h3>\n<p>DiT 最后一个 block 输出后，无论前面走了多少 FP4 层，都要统一回到 BF16 再交给 VAE 解码。原因是 VAE 解码器对输入分布的微小偏移极敏感：低精度尾数带来的系统性偏差会在上采样与卷积中被放大成色彩漂移与细节丢失，而这类误差不会在 DiT 的 FID 指标上暴露，只在最终图像上显现。这一步的输入是 DiT 末层激活（可能是 FP8 或 FP4 反量化后的 BF16），输出是 BF16 latent 供 VAE 分块解码；代价是一次全量激活的类型转换与可能的显存搬运，量级不大但不可省。工程判断：把「回 BF16」做成 DiT 出口的强制契约，而不是让各层自由决定输出精度，可以在框架层用类型断言拦住配置错误——这是失败模式里最容易被漏掉、也最容易在换分辨率后被触发的一条。</p>\n<p>与 VAE 分块解码的衔接点在于：分块解码按 tile 读 latent，若 latent 仍是低精度打包格式，每个 tile 都要重复反量化，且块边界与 VAE tile 边界不对齐会引入接缝。统一回 BF16 后，VAE 侧只面对一种格式，分块调度可以独立优化。代价是 BF16 latent 的显存占用回升，但相对 KV/中间激活缓存只是小头；真正占显存的是 DiT 内部的激活缓存，那部分在 FP4 化后已大幅下降，足以支撑更大 batch 或更高分辨率。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-12\">十二 · 端到端代价核算：每一步落在延迟、吞吐还是显存上</h3>\n<table class=\"mini\">\n<thead><tr><th>步骤</th><th>输入 → 输出</th><th>主要代价</th><th>兑现条件</th></tr></thead>\n<tbody>\n<tr><td>离线敏感度分析</td><td>校准集 → 层标签表 + scale</td><td>离线算力与工程时间，换模型/分辨率重跑</td><td>标签表版本化随模型发布</td></tr>\n<tr><td>权重量化落盘</td><td>BF16 权重 → 4bit + 两级 scale</td><td>加载期打包，显存降至 1/4 加 scale 开销</td><td>布局与 kernel 读取顺序对齐</td></tr>\n<tr><td>按标签分派 GEMM</td><td>BF16 latent → FP4/FP8 分支输出</td><td>kernel 切换气泡，窄 M 下 tile 利用率低</td><td>手写融合 kernel 消掉队列切换</td></tr>\n<tr><td>反量化汇合残差</td><td>两分支输出 + scale → BF16 激活</td><td>epilogue 带宽与寄存器压力</td><td>分段归约与残差/LN 融合深度实测</td></tr>\n<tr><td>回 BF16 交 VAE</td><td>末层激活 → BF16 latent</td><td>一次类型转换与搬运，量级小</td><td>出口强制契约，框架层类型断言</td></tr>\n</tbody>\n</table>\n<p>把五步串起来看，延迟的大头在第三步的分派与切换，吞吐的大头在 FP4 GEMM 的兑现率，显存的大头在权重与激活缓存的 1/4 化，而精度风险集中在第一、四、五步的接缝。一个具体工程判断：若服务 SLO 以单图端到端时延计、batch 取 1–8，则切换气泡的相对占比随 batch 减小而上升，此时应优先把相邻的 FP4 层合并成连续段、把 FP8 层聚到段边界，用「段内融合、段间切换」的布局把切换次数从逐层降到逐段；这不会改变 $\\alpha_{\\text{fp4}}$，但能显著改善实际兑现率，也是在敏感层比例无法再降时的最后一档优化空间。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-13\">十三 · 分派粒度与融合边界：混合精度在真实链路里会在哪里失效</h3>\n<p>按层标签分派听起来是零成本的，实际代价藏在“分派粒度”上。若以层为单位打标签，一个 DiT block 内 FP4 与 FP8 的 GEMM 交替出现，每次切换都意味着一次 kernel launch、一次队列切换与一次同步点；批大小取 1–8 的单步前向本就难以摊薄启动开销，切换次数随 block 数线性增长，调度碎片化会直接吃掉 NVFP4 相对 FP8 的 2 倍吞吐余量。可行做法是把同标签的相邻层聚成连续段，让 FP4 段内连续发射、FP8 段集中处理，代价是段边界处必须物化 BF16 中间张量，显存峰值上升；这也是“显存降至 BF16 的 1/4”只在权重与稳态激活上成立、峰值仍受残差汇合点约束的原因。融合 kernel 的收益可用下式粗估：<div class=\"formula\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</div>其中 $\\alpha_{\\text{fp4}}$ 为走 FP4 的 GEMM 时间占比。敏感层比例越高，$\\alpha_{\\text{fp4}}$ 越小，理论加速越接近 1；当敏感层占到相当比例时，混合精度相对纯 FP8 的时延收益被压缩到个位数百分比，而工程链路却长出校准与融合两段。</p>\n<p>失效条件集中在三处。其一，层敏感度依赖离线校准集的 kurtosis 与 max/mean 比统计，换模型或换分辨率必须重跑；分布外提示会让被判低敏感的层误差放大，因为两级 micro-block scaling 只把 E2M1 的动态范围拉回可用区间，块内若仍存在未被隔离的 outlier，$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}}$ 的块级缩放会被单个极值拖偏，同块其余权重有效位数被压缩，误差按 $\\text{err}_{\\ell} \\propto \\max|a_\\ell|/\\text{rms}(a_\\ell)$ 放大。其二，FP4 分支输出经 block scale 反量化后与 FP8 分支在 BF16 残差处汇合，汇合点若放在 attention 输出投影之后而非之前，残差流已被低精度污染，后续层无法恢复。其三，VAE 解码前未统一回 BF16 会造成解码器输入精度断层，表现为色彩漂移与高频细节丢失——这类退化不体现在 FID 的 1–2 个点预算内，却直接可见。</p>\n<p>系统代价要按请求形态算：DiT 单步前向的批量 latent 生成，SLO 以单图端到端时延计，批大小受显存与 SLO 夹在 1–8。低精度使中间激活缓存显存大幅下降，可容纳更大 batch 或更高分辨率，但 batch 增大后 FP4/FP8 切换的同步开销被摊薄、融合 kernel 的收益才显现；反之小 batch 下碎片化主导，实测吞吐可能远低于 2 倍的理论值。工程判断是：主体 GEMM 占主导、显存紧张、且团队能承担离线校准与手写融合 kernel 成本时才上这套方案；若敏感层比例偏高或分辨率频繁切换，纯 FP8 加注意力优化的链路更稳。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>离线校准</td><td>校准集激活</td><td>层敏感标签</td><td>换模型/分辨率需重跑</td></tr><tr><td>FP4 GEMM</td><td>NVFP4 权重+块缩放</td><td>块缩放反量化结果</td><td>切换与同步开销</td></tr><tr><td>BF16 汇合</td><td>两分支输出</td><td>残差流</td><td>中间张量显存峰值</td></tr><tr><td>VAE 前回 BF16</td><td>低精度 latent</td><td>BF16 latent</td><td>一次全量转换带宽</td></tr></tbody></table>\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-14\">十四 · 两级缩放的逐项拆解</h3>\n<p>NVFP4 的权重量化写成 <span class=\"formula\">$$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}},\\qquad \\hat{w}_i\\in\\text{E2M1}$$</span> 时，三个因子各司其职，不能混着看。<span class=\"formula\">$$\\hat{w}_i$$</span> 是 4 bit 尾数，E2M1 的编码空间只有 1 位符号、2 位指数、1 位尾数，可表示的非零幅值集合极小，正数侧只有有限的几档，且相邻档位之间是 2 倍关系而非线性等距。这意味着 E2M1 天生是“浮点骨架”，动态范围靠指数撑，精度靠尾数撑，而尾数只有 1 位，相对精度上限被锁死在约 2 的幂次间隔上。第二级 <span class=\"formula\">$$s_{\\text{block}}$$</span> 是块级缩放，按固定长度的 micro-block（典型为 16 个元素一组）各自算一个缩放因子，把该块内的幅值拉到 E2M1 的有效区间；第三级 <span class=\"formula\">$$s_{\\text{tensor}}$$</span> 是张量级缩放，一个权重张量共享一个全局因子，负责吸收块间整体量级的偏移。两级缩放的分工是：<span class=\"formula\">$$s_{\\text{tensor}}$$</span> 做粗对齐，避免不同块之间因为整体量级差异导致块级缩放因子本身进入不健康的数值区间；<span class=\"formula\">$$s_{\\text{block}}$$</span> 做细对齐，让每个 16 元素块内部的 E2M1 码点分布尽量铺满可用档位。</p>\n<p>推导的关键一步在块级缩放的选取准则。设块内元素为 <span class=\"formula\">$$a_1,\\dots,a_B$$</span>，若以最大绝对值定标，则 <span class=\"formula\">$$s_{\\text{block}}=\\max_i|a_i|/c_{\\max}$$</span>，其中 <span class=\"formula\">$$c_{\\max}$$</span> 是 E2M1 可表示的最大幅值。这一步把“块内最大值必须可表示”作为硬约束，代价是块内小幅值元素被压到 E2M1 的低档位甚至下溢。反过来若以均方根定标，<span class=\"formula\">$$s_{\\text{block}}=\\mathrm{rms}(a)/c_{\\text{rms}}$$</span>，则小元素保真更好，但块内尖峰会被截断。NVFP4 走的是前者加张量级兜底的路线，因此块内 outlier 的代价不是被截断，而是把同块其余元素的有效位数吃掉——这正是为什么敏感层不能只靠调 <span class=\"formula\">$$s_{\\text{block}}$$</span> 解决，必须整层退出 FP4。</p>\n<p>工程代价直接落在显存与带宽上。权重从 BF16 的 16 bit 降到 4 bit 尾数加两级缩放，缩放因子的开销必须计入：每 16 个元素一个块级因子，若因子用 FP8 存，则每元素平均额外 0.5 bit，加上张量级因子可忽略，实际每权重约 4.5 bit，相对 BF16 是 1/4 量级而非精确 1/4。这个差额在 KV 指中间激活缓存时同样成立：激活按 token 分块量化，块因子随激活一起驻留，显存下降幅度略小于权重侧，但对“容纳更大 batch 或更高分辨率”的判断不构成方向性影响。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-15\">十五 · 误差上界的来源与敏感层判据</h3>\n<p>给定公式中的 <span class=\"formula\">$$\\text{err}_{\\ell}\\propto \\frac{\\max|a_\\ell|}{\\mathrm{rms}(a_\\ell)}$$</span> 不是拟合出来的经验式，而是从块级定标准则直接推出来的比例关系。以最大绝对值定标时，块内量化步长正比于 <span class=\"formula\">$$\\max|a_\\ell|$$</span>，而量化噪声的绝对幅度正比于步长；把噪声折算成相对误差时除以该层的信号强度 <span class=\"formula\">$$\\mathrm{rms}(a_\\ell)$$</span>，就得到上式。它说明一件事：决定一层能否进 FP4 的不是绝对幅值，而是幅值的尖峰度——max 与 rms 的比值越大，同样的块定标把越多元素推进低档位，相对误差越大。这也解释了为什么用 kurtosis 与 max/mean 比做离线判据是合理的：两者都是尖峰度的代理量，kurtosis 对重尾更敏感，max/mean 比对单点尖峰更敏感，二者同时偏高才标记为高敏感层。</p>\n<p>推导中容易被忽略的一步是跨块耦合。上式是对单块写的，但一层内不同块的 <span class=\"formula\">$$\\max|a_\\ell|$$</span> 差异很大时，块级因子本身跨度大，反量化时各块噪声不再同分布，误差会在后续 GEMM 的累加中非相干叠加。因此实际判据要在层粒度上取块间因子的离散度作为二次筛选：块因子方差大的层，即使平均 max/rms 不高，也倾向保留 FP8。这一步把“逐项公式”变成“层标签”，是离线分析真正落地的地方。</p>\n<p>代价体现在校准链路上。敏感度分析需要离线校准集跑一遍前向、逐层统计 kurtosis 与 max/mean 比，换模型或换分辨率必须重跑，这是纯 FP8 方案没有的固定开销。具体例子：timestep embedding 的 MLP 在扩散早期步的激活尖峰极强，max/rms 比远高于主体线性层，被标为高敏感后整层保 FP8；attention 输出投影同理，因为注意力输出的通道间幅值分布高度不均，块定标会把弱通道压没。这两类层退出 FP4 后，主体 GEMM 仍占绝大多数，收益结构不变。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-16\">十六 · 加速比的代数结构与 α 的含义</h3>\n<p>公式 <span class=\"formula\">$$\\text{Speedup}\\approx\\frac{1}{\\alpha_{\\text{fp4}}+(1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</span> 把端到端加速拆成两个可测的量。<span class=\"formula\">$$\\alpha_{\\text{fp4}}$$</span> 是走 NVFP4 路径的计算量占比，<span class=\"formula\">$$\\alpha_{\\text{fp8}}$$</span> 是走 FP8 路径的占比，剩余部分为 BF16 及其他非 GEMM 开销。分母的第二项用 0.5 表达“FP8 相对 BF16 的时延减半”，第一项隐含“FP4 相对 BF16 时延为 1/4”——因为 NVFP4 吞吐为 FP8 的 2 倍，而 FP8 已是 BF16 的一半。这个式子的关键读法是：加速比不由 FP4 占比单独决定，而由 FP4 与 FP8 的混合比例共同决定，且分母里没有 BF16 项，意味着它只在 GEMM 主导、非 GEMM 开销可忽略时成立。</p>\n<p>把数字代进去看结构。若 <span class=\"formula\">$$\\alpha_{\\text{fp4}}=0.8$$</span>、<span class=\"formula\">$$\\alpha_{\\text{fp8}}=0.2$$</span>，分母为 0.8+0.1=0.9，加速比约 1.11；若 <span class=\"formula\">$$\\alpha_{\\text{fp4}}=0.6$$</span>、<span class=\"formula\">$$\\alpha_{\\text{fp8}}=0.4$$</span>，分母为 0.6+0.3=0.9，加速比同为 1.11。这说明在 FP8 时延减半的假设下，把一层从 FP8 挪到 FP4 带来的边际收益是固定的，敏感层比例上升会线性吃掉收益，但不会出现断崖——断崖来自 kernel 碎片化，不来自这个代数式。规模上限受 outlier 层比例约束，敏感层越多 FP4 收益越小，这句话在这个式子里就是 <span class=\"formula\">$$\\alpha_{\\text{fp4}}$$</span> 被压低。</p>\n<p>这个式子的工程价值在于它是容量规划的第一刀：给定模型各层敏感度标签，先算出 <span class=\"formula\">$$\\alpha_{\\text{fp4}}$$</span> 与 <span class=\"formula\">$$\\alpha_{\\text{fp8}}$$</span>，就能判断这套混合精度值不值得上。若算出来加速比接近 1，说明敏感层占比过高，应退回纯 FP8；若明显大于 1，才进入 kernel 融合的投入。代价侧要同时看：FP4 与 FP8 分支混跑导致调度碎片化，理论吞吐要靠手写融合 kernel 兑现，这个式子是上界而非承诺。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-17\">十七 · 分派与汇合的伪代码</h3>\n<p>把机制落到可实现层面，核心是一个按层标签分派的 GEMM 调度器加一个 BF16 残差汇合点。伪代码思路如下：对每一层线性算子，查标签表得到精度档位；FP4 分支取预存的 4 bit 权重与两级缩放因子，调用 Blackwell 原生 FP4 Tensor Core 路径，输出先经 <span class=\"formula\">$$s_{\\text{block}}\\cdot s_{\\text{tensor}}$$</span> 反量化到 BF16；FP8 分支走 FP8 GEMM；两分支结果在残差加法处按 BF16 汇合，再进入下一层。关键约束是汇合必须在 BF16 做，不能在 FP4 域做加法，否则残差通路本身被量化污染。</p>\n<p>伪代码的结构可以写成：<span class=\"formula\">$$\\text{for } \\ell \\text{ in layers}: \\text{tag}=\\text{label}[\\ell];\\ \\text{if tag}=\\text{FP4}: y=\\text{dequant}(\\text{gemm\\_fp4}(x_q,w_q, s_b,s_t));\\ \\text{else}: y=\\text{gemm\\_fp8}(x_q,w_q);\\ y\\leftarrow y+\\text{residual}_{\\text{bf16}}$$</span>。这里 <span class=\"formula\">$$x_q$$</span> 是激活量化后的表示，激活侧同样按块量化，块因子随激活一起进 GEMM 的反量化路径。分派粒度是层而非算子内部，这是为了避免同一 GEMM 内部混精度导致指令流分裂；代价是层边界处必须做一次精度转换，转换点越多，融合 kernel 的编写难度越大。</p>\n<p>汇合点的位置有讲究。FP4 GEMM 输出反量化后与 FP8 分支在 BF16 残差处汇合，意味着残差流全程保持 BF16，只有进入 GEMM 前的激活被降精度。这样做的代价是残差流的显存与带宽没有随权重一起下降，KV 指中间激活缓存时，残差缓冲仍是 BF16 占大头；收益是数值稳定性——残差是跨层累加通路，一旦被量化，误差会沿深度累积，结构崩坏往往从这里开始。具体例子：一个 DiT block 内 attention 输出投影走 FP8、FFN 主体走 FP4，两者输出在 block 残差处汇合，若把汇合点提前到 FP4 域，色彩漂移会在多步采样后放大。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-18\">十八 · 融合 kernel 的碎片化代价</h3>\n<p>分派逻辑本身很轻，真正的工程代价在 kernel 层。FP4 与 FP8 分支交替出现时，每个分支都要自己的量化、GEMM、反量化三段，若各自独立 launch，则层间出现大量小 kernel 与同步点，调度碎片化使实际吞吐远低于理论值。兑现理论吞吐的唯一路径是把“量化—GEMM—反量化—残差汇合”融进一个 kernel，让 FP4 与 FP8 分支在同一 grid 内按层标签走不同代码路径，共享输入激活的加载与残差的读写。</p>\n<p>融合 kernel 的伪代码思路是：一个 block 处理一个输出 tile，先读层标签，若为 FP4 则加载 4 bit 权重与块因子、执行 FP4 MMA、按 <span class=\"formula\">$$s_{\\text{block}}\\cdot s_{\\text{tensor}}$$</span> 反量化累加；若为 FP8 则加载 FP8 权重执行 FP8 MMA；两条路径在寄存器内汇合到同一累加器，最后一次性写 BF16 残差。这样做的代价是 kernel 复杂度高、寄存器压力大，且 FP4 与 FP8 的 MMA 指令形状不同，tile 划分要兼顾两者，不能各自最优。收益是把层间同步点消掉，碎片化代价从“每层一次 launch”降到“每 block 一次分支”。</p>\n<p>失败模式在这里最集中：未手写融合 kernel 时，调度碎片化让加速比公式的上界失效，实际吞吐可能只拿到 FP8 的水平；换模型或换分辨率未重跑敏感度分析，outlier 层被误压到 NVFP4，结构崩坏；VAE 解码前未统一回 BF16，解码器输入精度断层引起色彩漂移与细节丢失。这三条都指向同一个工程判断：混合精度的收益不在量化本身，而在分派、汇合、融合三处的实现质量，公式给出的是天花板，落地拿到的比例取决于这三处的打磨程度。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-19\">十九 · 失效边界：敏感层比例、分布外激活与分支碎片化</h3>\n<p>本方案的收益上限由敏感层占比直接决定。设 FP4 覆盖的线性层 FLOPs 比例为 α<sub>fp4</sub>，则理想加速比约为 Speedup ≈ 1 / [α<sub>fp4</sub> + (1−α<sub>fp4</sub>)·0.5]，因为未覆盖部分按 FP8 的 2 倍吞吐折算。timestep MLP 与 attention 输出投影一旦被大量标记为高敏感，α<sub>fp4</sub> 下降，加速比向 1 收敛；极端情形下所有层回退 FP8，NVFP4 只剩显存收益（1/4 于 BF16）而无时延收益。因此离线校准阶段必须输出每层 kurtosis 与 max/rms 的比值，并把 err<sub>ℓ</sub> ∝ max|a<sub>ℓ</sub>| / rms(a<sub>ℓ</sub>) 作为排序依据，而不是凭经验拍层号。</p>\n<p>失效条件有三类，且都落在工程链路上。其一，换模型或换分辨率未重跑敏感度分析，原判为低敏感的层在新分布下 outlier 放大，被压到 NVFP4 后结构崩坏——这是最贵的错误，因为它在离线阶段不可见。其二，FP4 与 FP8 分支混跑导致 kernel 调度碎片化：每层分派到不同 GEMM 队列，launch 开销与队列切换吃掉理论吞吐，只有手写融合 kernel 把两条分支的反量化与残差汇合压进同一 kernel，Speedup 公式里的 0.5 才成立，否则实测远低于理论值。其三，VAE 解码前未统一回 BF16，解码器输入出现精度断层，表现为色彩漂移与细节丢失，这类退化在 FID 上未必显著却在人眼评审中直接判负。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发点</th><th>系统代价</th></tr></thead><tbody><tr><td>敏感层误判</td><td>换模型/分辨率未重校准</td><td>结构崩坏，整批 latent 报废</td></tr><tr><td>分支碎片化</td><td>无融合 kernel</td><td>吞吐低于理论值，launch 开销占比上升</td></tr><tr><td>解码精度断层</td><td>VAE 前未回 BF16</td><td>色彩漂移，端到端 SLO 达标但质量不达标</td></tr></tbody></table>\n<p>两级 micro-block scaling 的边界同样明确：w<sub>i</sub> = ŵ<sub>i</sub> · s<sub>block</sub> · s<sub>tensor</sub>，ŵ<sub>i</sub> ∈ E2M1。块级缩放吸收通道内 outlier，张量级缩放把整体动态范围拉回 E2M1 可用区间；但当某通道 max/rms 比高到块内其余元素被压进 E2M1 的最小非零档时，反量化后的残差已无法由 BF16 汇合补偿，此时唯一出路是把该层整体移出 FP4 队列。这也是敏感层比例构成规模上限的原因：FP4 收益随敏感层增多而线性衰减，而离线校准与融合 kernel 的固定成本不随模型缩小，小分辨率、少步数的部署场景往往不划算。</p>\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-20\">二十 · 请求形态：单步前向的批量 latent 才是主战场</h3>\n<p>NVFP4 混合精度 DiT 的收益结构，决定了它只对一种请求形态友好：以 DiT 单步前向为单位、把多张 latent 拼成一个批次的批量生成。原因不在算法而在 kernel 粒度——FP4 GEMM 的 block scale 反量化与 FP8 分支的汇合都发生在层边界，批越大，单次层调用摊掉的调度与反量化开销越小，Tensor Core 才真正被喂饱。反过来，如果服务端把请求拆成 batch=1 的逐张串行，每层只做一次极小的 FP4 GEMM，block scale 的读取与分支判定开销占比上升，理论上的 2 倍 FP8 吞吐根本兑现不出来。</p>\n<p>批大小的取值区间被显存与 SLO 两头夹住：给定事实给出的配方是 1–8。下界 1 是保底形态，用于高分辨率或长序列导致中间激活撑爆显存的场景；上界 8 不是硬件极限，而是 SLO 约束下的经验拐点——SLO 以单图端到端时延计，批内第 8 张图的排队时延已经吃掉相当一部分预算。写成约束就是：</p>\n<div class=\"formula\">$$B^\\* = \\arg\\max_{B}\\ \\frac{B}{\\tau_{\\text{queue}}(B)+\\tau_{\\text{step}}(B)}\\quad \\text{s.t.}\\ \\tau_{\\text{queue}}(B)+\\tau_{\\text{step}}(B)\\le \\text{SLO}_{\\text{e2e}}$$</div>\n<p>其中 $\\tau_{\\text{step}}$ 随 $B$ 增长而次线性上升（GEMM 摊薄），$\\tau_{\\text{queue}}$ 随 $B$ 线性上升。两者相加的曲线在 1–8 之间通常存在一个使有效吞吐最大、又不破 SLO 的点。工程判断是：先把 $B$ 顶到显存允许的上限测 $\\tau_{\\text{step}}$，再用 SLO 反推可接受的排队上限，而不是反过来。</p>\n<p>具体例子：一个 1024×1024 潜空间的 DiT 服务，若中间激活缓存（KV 指中间激活缓存）在 BF16 下占显存主项，切到 NVFP4 主体 GEMM 后显存降至 1/4，原本只能跑 batch=2 的卡可以容纳 batch=6–8；但若 SLO 卡在单图 2 秒级，batch=8 的尾图排队时延会把端到端推过线，实际应停在 4–6。这就是“显存允许”与“SLO 允许”两个不同上限的典型分离。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-21\">二十一 · 长度分布：分辨率与序列长度决定批的可行域</h3>\n<p>扩散模型的“长度”不是文本 token 数，而是潜空间补丁序列长度，它由分辨率与 patch size 共同决定，且直接进入注意力与 GEMM 的 $O(N^2)$ 项。NVFP4 混合精度只压缩线性层，注意力的 QK^T 与 AV 仍走 FP8 或 BF16（见本套书 DiT FP8 注意力与 GEMM 条目），因此序列一长，注意力重新成为主项，FP4 对端到端时延的边际贡献迅速衰减。这意味着负载配方必须按长度分档，而不是一套批大小打天下。</p>\n<p>设线性层耗时 $T_{\\text{lin}}\\propto B\\cdot N\\cdot d^2$、注意力耗时 $T_{\\text{attn}}\\propto B\\cdot N^2\\cdot d$，则 FP4 带来的端到端加速比为：</p>\n<div class=\"formula\">$$\\text{Speedup}_{\\text{e2e}}\\approx\\frac{T_{\\text{lin}}+T_{\\text{attn}}}{T_{\\text{lin}}/\\text{Speedup}_{\\text{fp4}}+T_{\\text{attn}}}$$</div>\n<p>其中 $\\text{Speedup}_{\\text{fp4}}$ 由主体 GEMM 的 FP4 占比决定，可近似用 $\\dfrac{1}{\\alpha_{\\text{fp4}}+(1-\\alpha_{\\text{fp8}})\\cdot 0.5}$ 估算（$\\alpha_{\\text{fp4}}$ 为走 FP4 的 GEMM 时间占比）。序列越长，$T_{\\text{attn}}$ 占比越高，分母里未被加速的部分越大，整体加速比被稀释。所以低分辨率、短序列、线性层占主导的请求，是这套方案的最佳负载；高分辨率长序列请求则退化为“显存收益为主、时延收益为辅”。</p>\n<p>长度分布还影响批的可行域：同一 batch size 下，长序列请求的中间激活缓存占用按 $B\\cdot N\\cdot d$ 增长，NVFP4 把权重压到 BF16 的 1/4 只释放了权重侧显存，激活侧仍受序列长度支配。混合长度批次（一张 512、一张 1024）若不做分桶，短图会被长图的显存与算力需求拖住，等效于用长序列的代价服务短序列请求。工程做法是按分辨率分桶、桶内定批，桶间共享同一套层标签与 kernel 队列，避免为每个桶重跑敏感度分析。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-22\">二十二 · 并发与批大小：连续批处理在扩散服务里的变形</h3>\n<p>扩散推理没有自回归解码那样的逐 token 连续批处理语义，但服务化场景下仍存在请求到达的泊松式并发。NVFP4 混合精度 DiT 的并发配方本质是“静态批 + 队列深度”的组合：DiT 单步前向是批内同步的，一个批次内所有 latent 必须等最慢的那张走完全部层才能出结果，因此批内方差直接转化为尾延迟。并发高时，正确做法是维持多个固定大小的批次在流水上轮转，而不是把批撑大。</p>\n<p>设到达率 $\\lambda$、单批服务时间 $\\tau(B)$、批大小 $B$，则系统吞吐上限为 $B/\\tau(B)$，而排队时延随 $\\lambda$ 逼近该上限而发散。NVFP4 把 $\\tau(B)$ 压低后，同一 $\\lambda$ 下的队列长度下降，等效于在不加卡的前提下提高并发承载力。但这里有个陷阱：FP4 与 FP8 分支混跑导致 kernel 调度碎片化，$\\tau(B)$ 并非随 $B$ 平滑下降，而是在某些 $B$ 上出现台阶——分支切换的同步点让批次内出现空转。手写融合 kernel 把这些分支合并进同一调度单元，才能让 $\\tau(B)$ 曲线变平滑，批大小的选择也才有连续可调的空间。</p>\n<p>具体例子：一个在线出图服务，到达率折算为每秒若干净批，单批 $\\tau(4)$ 因融合 kernel 从“理论值加碎片开销”降到接近理论值，则同样卡数下可维持的并发批次从 2 提到 3，尾延迟分位数明显收敛。反之，未做融合 kernel 时，$B$ 从 4 加到 8 带来的吞吐增益可能被分支同步开销抵消，表现为“加批不加吞吐”。这就是负载配方里必须把 kernel 融合状态作为批大小选择的前置条件，而不是事后优化。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-23\">二十三 · 负载不对时：三类可观测的退化</h3>\n<p>第一类是批过小导致的“理论吞吐悬空”。batch=1 时 FP4 GEMM 的 block scale 反量化与 FP8 汇合开销占比高，实测吞吐远低于 FP8 的 2 倍理论值，甚至可能不如纯 FP8 方案——因为纯 FP8 没有分支切换成本。可观测信号是 SM 利用率低、kernel 启动间隔占比高。判断标准：若单层 FP4 GEMM 的实际耗时与理论耗时的比值随 $B$ 显著下降，说明当前负载落在摊薄不足的区间，应合并请求而非加卡。</p>\n<p>第二类是长度分布错配导致的“加速比稀释”。服务端混入大量高分辨率长序列请求时，注意力占比上升，端到端加速比按上面的公式被压到接近 1，而显存却因激活缓存膨胀而吃紧。此时 NVFP4 的显存收益（权重 1/4）被激活侧抵消，批大小反而要下调。可观测信号是 $T_{\\text{attn}}/T_{\\text{lin}}$ 比值上升、批大小被迫收缩。工程判断是：这类负载应路由到纯 FP8 或 BF16 档位，而不是硬套 NVFP4 配方。</p>\n<p>第三类最隐蔽：分布外提示让被判低敏感层误差放大。层敏感度分析依赖离线校准集，校准集覆盖不到的提示分布会把某些“低敏感”层的激活推入 E2M1 的动态范围边缘，两级 micro-block scaling 也拉不回来，表现为结构崩坏或局部伪影。可观测信号是输出 FID 退化超出 1–2 个点的预期区间、且退化集中在特定提示类别。这不是批大小能修的，只能靠扩充校准集或对争议层回退 FP8。三类退化对应三种不同的负载错配，排查顺序应是先看批与 kernel 状态，再看长度构成，最后才怀疑校准集覆盖。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-24\">二十四 · 配方落地：把负载条件写进部署参数</h3>\n<p>把上述约束固化成部署配方，需要三个联动参数：批大小区间、分辨率分桶表、层标签版本。批大小区间按显存上限与 SLO 反推取 1–8；分辨率分桶表决定每桶的序列长度与激活缓存预算；层标签版本绑定校准集，换模型或换分辨率必须重跑敏感度分析并升版本，否则旧标签会把新分布下的 outlier 层误压到 NVFP4。三者中任何一个变动，都要重新验证 $\\tau(B)$ 曲线，因为 kernel 碎片化的台阶位置会随层标签比例变化而移动。</p>\n<p>容量规划上，NVFP4 的显存收益（权重降至 BF16 的 1/4）应优先兑换成“更大批或更高分辨率”，而不是直接兑换成“更少卡”。原因是批大小的吞吐增益在 1–8 区间内是次线性的，而分辨率提升带来的请求价值是离散的；把显存红利投到分辨率上，单位卡的服务价值更高，代价是注意力占比上升、FP4 加速比被稀释——这正是需要按桶分别核算的原因。规模上限受两个比例约束：outlier 层占比越高，走 FP4 的 GEMM 时间占比 $\\alpha_{\\text{fp4}}$ 越低，加速比越接近 1；kernel 碎片化越严重，$\\tau(B)$ 的实际值越偏离理论值。两个比例共同决定这套配方在特定服务上是否值得上。</p>\n<p>最后落在工程判断上：负载配方的核心不是选一个批大小数字，而是维护一条“批大小—序列长度—层标签”的三维可行域，并在每次模型、分辨率或校准集变动时重测这条域的边界。NVFP4 混合精度 DiT 的收益只在这条域内成立，域外的请求应显式路由到 FP8/BF16 档位，而不是靠调批大小硬凑。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-25\">二十五 · 负载配方：批大小、长度分布与失效边界</h3>\n<p>这套混合精度方案的服务对象很窄：DiT 单步前向的批量 latent 生成，批大小按显存与 SLO 取 1–8，SLO 以单图端到端时延计。批大小的上限不是由算力决定，而是由 FP4 分支与 FP8 分支并存带来的显存驻留决定的——NVFP4 权重只占 BF16 的 1/4，但高敏感层仍以 FP8 甚至 BF16 常驻，实际显存收益介于两者之间，因此 batch 能放大多少取决于敏感层比例。收益的解析上界可由 Amdahl 型式子给出：</p>\n<div class=\"formula\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</div>\n<p>其中 $\\alpha_{\\text{fp4}}$ 是走 NVFP4 的 GEMM 时间占比。当敏感层（timestep MLP、attention 输出投影）占比升高，$\\alpha_{\\text{fp4}}$ 下降，2 倍吞吐的理论值迅速被稀释；敏感层越多，FP4 收益越小，这是规模上限的第一道约束。第二道约束是 kernel 碎片化：FP4 与 FP8 分支混跑使调度在两种 GEMM 队列间切换，若没有手写融合 kernel，实际吞吐远低于理论值，batch 越大切换开销越被摊薄、但小 batch 时碎片化代价最重，因此 1–2 的极小 batch 反而是这套方案最不划算的负载形态。</p>\n<p>长度分布上，它适合分辨率固定、latent 网格尺寸稳定的服务化请求。层敏感度分析依赖离线校准集，换模型或换分辨率必须重跑，否则被判为低敏感的层被误压到 NVFP4，outlier 通道误差被 E2M1 的窄动态范围放大，直接表现为结构崩坏而非轻微画质下降。分布外提示同样危险：校准集未覆盖的 prompt 会让低敏感层的激活 kurtosis 与 max/mean 比漂移，误差按 $\\text{err}_{\\ell} \\propto \\max|a_\\ell|/\\text{rms}(a_\\ell)$ 放大，两级 micro-block scaling 也拉不回来。这类负载下应回退到纯 FP8 路径，而不是硬扛 FP4。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>适配判断</th><th>主要代价</th></tr></thead><tbody><tr><td>固定分辨率、batch 4–8 的服务化生成</td><td>适配，主体 GEMM 占主导</td><td>需融合 kernel 兑现吞吐</td></tr><tr><td>batch 1–2 的低延迟单发</td><td>不适配，碎片化开销占比高</td><td>调度切换吃掉收益</td></tr><tr><td>多分辨率/换模型的热切换</td><td>不适配，需重跑敏感度分析</td><td>离线校准链路长</td></tr><tr><td>分布外 prompt 密集</td><td>需回退 FP8</td><td>outlier 层误压致结构崩坏</td></tr></tbody></table>\n<p>还有一个与负载直接耦合的失效点：VAE 解码前必须统一回 BF16。若为省显存让解码器直接吃低精度输入，会造成精度断层，表现为色彩漂移与细节丢失——这类退化不体现在 DiT 单步时延上，却直接违反以单图端到端时延计的 SLO 语义。工程判断是：把 batch 上限、分辨率档位与 prompt 分布一起写进校准与回归清单，任何一项变动都触发敏感度重跑与融合 kernel 的重新验证，否则这套方案的收益只存在于理论吞吐表里。</p>\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-26\">二十六 · 硬件档位与并行拓扑的耦合</h3>\n<p>部署配方的第一层决策不是量化，而是把硬件档位与并行拓扑钉死。Blackwell 上 NVFP4 的吞吐是 FP8 的两倍、权重显存是 BF16 的四分之一，这两个比例决定了档位选择的方向：当单卡显存能容纳整模型 NVFP4 权重加中间激活缓存时，优先单卡；当模型规模超出单卡、或需要更高分辨率导致激活缓存膨胀时，才引入张量并行。张量并行在 DiT 上的代价与 LLM 不同——DiT 的 attention 与 MLP 层形状规整，切分维度干净，但每步前向只有一次，通信无法被多步解码摊薄，因此 TP 度每加一档，单步时延里的 all-reduce 占比就上升一截。工程判断是：TP 度取 2 或 4，且只在 NVLink 域内切分，跨节点不做 DiT 的 TP。GB200/GB300 NVL72 的机柜内 NVLink 5 域恰好覆盖这一需求，把 TP 组约束在单机柜内，避免 NCCL 走 IB 带来的时延抖动。并行拓扑还要与量化分层对齐：高敏感层保 FP8/BF16 后，这些层的 GEMM 尺寸与 FP4 层不同，若 TP 切分按统一维度做，FP8 分支可能出现切分后形状不整除的情况，需要在拓扑设计阶段就把敏感层的通道数纳入切分约束。</p>\n<p>硬件档位的第二个维度是 SM 利用率。NVFP4 走 tcgen05 的 FP4 Tensor Core 路径，要求 MMA 的 tile 形状与 block scale 的 micro-block 粒度匹配；FP8 分支走另一条 MMA 路径。两条路径在同一 SM 上混跑时，warp 调度器要在两个队列间切换，切换开销直接吃掉理论吞吐的一部分。因此档位选择要预留 SM 预算：若敏感层比例高，FP8 分支占用 SM 时间变长，FP4 的 2 倍吞吐优势被稀释，此时应评估是否退回到纯 FP8 档位。这个判断可以用一个粗粒度的收益式表达：</p>\n<div class=\"formula\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</div>\n<p>其中 $\\alpha_{\\text{fp4}}$ 是走 FP4 路径的计算占比，$(1-\\alpha_{\\text{fp8}})$ 是 FP8 分支相对 FP4 的时延权重。敏感层越多，$\\alpha_{\\text{fp4}}$ 越小，整体加速越接近 1；只有当 $\\alpha_{\\text{fp4}}$ 足够大时，2 倍吞吐才在端到端时延上体现。这个式子不是精确模型，而是部署前做档位取舍的判据：先估敏感层比例，再决定是否值得上 NVFP4 混合精度。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-27\">二十七 · 量化方案的落地形态</h3>\n<p>量化方案在部署层面要落成三张表：层标签表、block scale 表、分支汇合表。层标签表来自离线敏感度分析，标记每个线性层走 FP4 还是 FP8/BF16；block scale 表是 NVFP4 权重的伴随数据，按两级 micro-block scaling 存储：</p>\n<div class=\"formula\">$$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}},\\qquad \\hat{w}_i\\in\\text{E2M1}$$</div>\n<p>其中 $\\hat{w}_i$ 是 4bit 尾数，$s_{\\text{block}}$ 是块级缩放，$s_{\\text{tensor}}$ 是张量级缩放。两级缩放的意义在部署上是显存布局问题：block scale 必须与权重同驻显存、同被 kernel 读取，若 scale 表布局与权重 tile 不对齐，kernel 会在反量化时产生额外的 gather 开销，把 FP4 的带宽优势抵消。工程做法是把 scale 表按 MMA tile 的 micro-block 粒度重排，使每个 tile 的 scale 连续存放，kernel 一次加载即可覆盖整个 tile 的反量化需求。分支汇合表则记录每个 FP4 分支的输出在哪个 BF16 残差处与 FP8 分支汇合，这张表决定了融合 kernel 的边界——汇合点越靠后，FP4 路径越长，融合 kernel 的复杂度越高但收益越大。</p>\n<p>量化方案的第三个落地项是校准集管理。层敏感度分析依赖离线校准集，换模型或换分辨率必须重跑，这不是一次性工作而是部署流水线的一个环节。校准集的构成要覆盖目标服务的提示分布：若服务面向多分辨率生成，校准集必须包含各分辨率的 latent 统计，否则被判低敏感的层在新分辨率下可能误差放大。部署配方应把校准集版本与模型版本、分辨率档位绑定，形成可追溯的配置三元组，避免用旧校准结果套新模型。这一步的代价是工程链路变长，但它是 FP4 混合精度能稳定服务的前提。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-28\">二十八 · 中间激活缓存（KV 策略）的容量换算</h3>\n<p>DiT 没有自回归 KV cache，这里的 KV 指中间激活缓存——attention 的 K/V 投影结果、以及跨块跳步所需的特征缓存。低精度化后这部分显存大幅下降，直接换算成 batch 上限或分辨率上限。设单步前向的激活缓存为 $M_{\\text{act}}$，其大小随分辨率平方增长、随 batch 线性增长；NVFP4 把权重压到 BF16 的四分之一后，权重占用让出的显存可以转给激活缓存，于是 batch 从 1–8 的区间里可以取到上限，或在固定 batch 下把分辨率推高一档。部署配方要做的换算是：先按 SLO 定单图端到端时延，再反推可接受的 batch，最后用剩余显存决定激活缓存的分辨率档位。这个顺序不能颠倒——先定分辨率再定 batch 会让时延目标失控。</p>\n<p>激活缓存的精度策略与权重不同：中间激活在 FP4 下误差放大更剧烈，尤其 attention 输出通道的 outlier，因此激活缓存通常保 FP8 或 BF16，只有被判低敏感的层才让激活走 FP4。这带来一个显存账：权重省下的四分之三显存，有一部分要被激活的 FP8/BF16 占用吃掉。部署时要分别核算权重显存与激活显存，不能只用权重比例推算总显存收益。工程判断是：当分辨率高、激活缓存占主导时，NVFP4 的显存收益主要体现在权重侧，激活侧收益有限；此时提升 batch 的空间来自权重让出的部分，而不是激活本身的压缩。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-29\">二十九 · 调度参数与 kernel 碎片化</h3>\n<p>调度参数的核心矛盾是 FP4 与 FP8 分支混跑造成的 kernel 调度碎片化。每个 DiT 单步前向要按层标签把 GEMM 分派到两个队列，若每个层单独 launch，launch 开销与队列切换开销会累积成可观的时延。部署配方要求把相邻的同标签层合并成组，减少 launch 次数；更进一步是手写融合 kernel，把 FP4 GEMM、block scale 反量化、与 FP8 分支的 BF16 汇合写进同一个 kernel，消除中间结果的显存往返。这一步是兑现理论吞吐的关键——不写融合 kernel，实际吞吐远低于 2 倍的理论值，碎片化会把收益吃掉大半。</p>\n<p>调度参数还包括 batch 内的层分派顺序。由于 FP4 与 FP8 分支在同一 SM 上竞争，调度器应让同标签的层连续执行，避免在 FP4 与 FP8 之间反复切换。伪代码思路是：按层标签把前向图重排成若干连续段，每段内所有层同标签，段间插入一次精度切换；切换点选在残差汇合处，因为那里本来就是 BF16 精度，切换不引入额外断层。这个重排对模型语义无影响，但对 kernel 调度友好。代价是重排后的执行顺序与原始层序不同，调试时需要保留原始层序的映射表。</p>\n<p>调度参数还要与 SLO 挂钩。单图端到端时延是 SLO 的计量单位，调度器要在时延预算内决定是否启用融合 kernel 路径、是否把某些层临时降级到 FP8 以避开 FP4 队列拥塞。这种动态降级需要层标签表支持运行时覆盖，部署配方应预留这个开关，但默认关闭——动态降级会破坏量化方案的一致性，只在时延超标时作为应急手段。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-30\">三十 · 一个可复现的配置思路</h3>\n<p>把上述决策串成一条可复现的配置链，顺序如下。第一步定硬件档位：单卡 Blackwell，若模型超出单卡显存则 TP=2 且约束在 NVLink 域内。第二步跑离线敏感度分析：用覆盖目标分辨率的校准集，按 kurtosis 与 max/mean 比标记高敏感层，timestep MLP 与 attention 输出投影默认进高敏感集。第三步定量化方案：高敏感层权重与激活保 FP8，其余层权重 NVFP4 加两级 block scale，scale 表按 MMA tile 粒度重排。第四步定激活缓存策略：权重让出的显存转给激活缓存，batch 在 1–8 内按 SLO 取上限，激活保 FP8/BF16。第五步写融合 kernel：FP4 GEMM、反量化、BF16 汇合三合一，段间切换点选在残差汇合处。第六步设调度参数：同标签层合并成组，预留动态降级开关但默认关闭。第七步验证：用端到端时延对 SLO，用 FID 退化对 1–2 个点的容忍度，两项都达标才上线。</p>\n<p>这条链的复现性依赖三个绑定：校准集版本绑定模型与分辨率、层标签表绑定量化方案、融合 kernel 版本绑定调度参数。任一绑定变更都要重跑验证。失败模式要提前设防：换模型或换分辨率未重跑敏感度分析，outlier 层被误压到 NVFP4 会导致结构崩坏；VAE 解码前未统一回 BF16，解码器输入精度断层会引起色彩漂移与细节丢失；未写融合 kernel 则碎片化让吞吐远低于理论值。这三条在配置链里各有对应的检查点，部署配方应把它们写成上线前的硬性 gate，而不是事后排查项。</p>\n<p>规模上限的判断落在敏感层比例上：敏感层越多，FP4 收益越小，当 $\\alpha_{\\text{fp4}}$ 低到加速式接近 1 时，应退回纯 FP8 档位。这个判断不需要实验数字，只需要离线分析给出的敏感层占比与加速式的粗算。配置链的最后一步不是收尾，而是把敏感层占比作为容量规划的输入——它决定了这套 NVFP4 混合精度配方在当前模型与分辨率下是否值得部署，以及 batch 与分辨率能推到哪一档。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-31\">三十一 · 配方边界：敏感层比例决定收益上限，融合 kernel 决定收益下限</h3>\n<p>这套部署配方的收益不是常数，而是被两个量夹住：高敏感层占比 α<sub>fp8</sub> 与融合 kernel 的兑现度。按 <span class=\"formula\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</span> 的粗算逻辑，若 timestep MLP 与 attention 输出投影合计占到主体 GEMM 的三成以上，理论加速就从 2 倍迅速滑向 1.4 倍附近；敏感层越多，NVFP4 的边际收益越薄。这正是配方失效的第一类条件：换模型或换分辨率后未重跑 kurtosis 与 max/mean 比分析，把原本被判低敏感的层误压到 E2M1，两级 micro-block scaling 也拉不回被 outlier 撕开的动态范围，结构崩坏直接体现在采样图上，而不是在 loss 曲线上。</p>\n<p>第二类边界在工程侧。FP4 与 FP8 两条 GEMM 队列按层标签分派，若没有手写融合 kernel，block scale 反量化、BF16 残差汇合与队列切换会引入额外 launch 与同步开销，调度碎片化使实际吞吐远低于理论值——此时即便显存已降至 BF16 的 1/4、单卡 batch 从 1 提到 8，端到端单图时延也可能不降反升。判断标准很直接：先用纯 FP8 路径测出单步前向的 kernel 时间占比，只有当主体 GEMM 占主导且融合 kernel 能把分支切换开销压进 GEMM 时间之内，这套配方才成立。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>敏感层误判</td><td>采样结构崩坏、FID 退化超 1–2 点</td><td>需回滚整层到 FP8，显存回升</td></tr><tr><td>无融合 kernel</td><td>SM 利用率抖动、launch 密集</td><td>吞吐兑现不了 2 倍，时延反超 FP8</td></tr><tr><td>VAE 前未回 BF16</td><td>色彩漂移、高频细节丢失</td><td>解码器输入精度断层，画质不可修</td></tr></tbody></table>\n<p>还有一个容易被忽略的代价项：离线校准集本身。敏感度分析依赖固定分布的校准样本，分布外提示（极端长宽比、异常文本条件）会让被判低敏感的层误差放大，而重跑分析意味着换模型、换分辨率都要重新走一遍链路，工程链路明显长于纯 FP8 方案。因此配方应把 α<sub>fp8</sub> 当作可调旋钮而非一次性结论：先用保守分层跑通，再按 FID 退化是否守在 1–2 点内逐层下压，同时把 VAE 解码前的 BF16 统一回归设为不可协商的硬约束——这一段的精度断层无法用任何 block scale 补偿。</p>\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-32\">三十二 · 显存账：权重、激活与中间缓存的四倍差从哪来</h3>\n<p>NVFP4 把权重压到 BF16 的 1/4，这个数字只对权重成立，不能直接外推到端到端显存。DiT 单步前向的显存由三块构成：权重、逐层激活（含 attention 的 QKV 与输出投影中间结果）、以及跨步保留的 latent 与条件张量。权重走 NVFP4 后按 <span class=\"formula\">$$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}}$$</span> 存储，每个 E2M1 尾数 4 bit，外加块级与张量级两个缩放因子；块越小缩放开销占比越高，micro-block 粒度直接决定实际压缩比能否贴近 4 倍。激活侧则受分层策略牵制：被标记为高敏感的 timestep MLP 与 attention 输出投影仍以 FP8 甚至 BF16 驻留，这部分激活不享受 4 倍红利。因此端到端显存收益是权重压缩比与敏感层占比的加权结果，敏感层越多，越接近 FP8 方案的显存水位而非 1/4。</p>\n<p>工程上的直接推论是：显存规划必须按“层标签”分段核算，而不是拿一个全局压缩比乘总参数量。举例而言，一个以主体线性层为主、敏感层集中在 timestep 分支与少数输出投影的 DiT，权重显存能明显下探，激活峰值却卡在 FP8 分支上；此时把 batch 从 1 提到 4 的瓶颈往往不是权重，而是 FP8 分支的激活峰值与 attention 的中间张量。反过来，若为了压激活把敏感层也塞进 NVFP4，就会触发结构崩坏这一类失败模式，收益是假的。显存账要按“权重省下来的空间能否被激活吃掉”来判断，这是规模上去后第一个要盯的量。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-33\">三十三 · 带宽与反量化：block scale 的读取代价</h3>\n<p>NVFP4 的 GEMM 在 Blackwell 原生 FP4 Tensor Core 上跑，但输出并非直接可用：FP4 结果需经 block scale 反量化后才能与 FP8 分支在 BF16 残差处汇合。这条反量化路径引入两类带宽开销。其一是缩放因子的读取：每个 micro-block 一组 <span class=\"formula\">$$s_{\\text{block}}$$</span>，块越小因子越密，缩放因子的字节数会随块粒度线性上升，挤占原本属于权重的带宽预算。其二是汇合点的数据搬运：FP4 分支反量化到 BF16、FP8 分支保持 FP8，两者在残差加法处必须统一到同一精度域，这一步的写回与再读取在层数多、分支切换频繁的模型上会累积成可观的片上与 HBM 流量。</p>\n<p>更隐蔽的代价来自 kernel 调度碎片化。FP4 与 FP8 分支混跑意味着同一个前向里存在两种 GEMM 队列，若没有手写融合 kernel，硬件会在两种 Tensor Core 路径之间反复切换，理论上的 2 倍 FP4 吞吐无法兑现——这正是“实际吞吐远低于理论值”的失败模式。融合 kernel 的价值在于把分派、反量化、残差汇合压进一个流水，让 FP4 分支的算力不被调度空隙吃掉。判断是否值得上 NVFP4，先看主体 GEMM 占比：主体 GEMM 占主导时，融合 kernel 摊薄后的收益才站得住；若模型里敏感层与分支切换过密，碎片化会把 2 倍理论吞吐折损到接近 FP8 的水平，此时混合精度的工程链路成本就不划算了。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-34\">三十四 · 通信：张量并行下的精度域对齐</h3>\n<p>单卡能装下时，NVFP4 混合精度几乎不引入新的通信面；一旦模型规模推高到需要张量并行，通信代价就浮出水面。张量并行在 attention 输出投影与 MLP 上做行/列切分，all-reduce 发生在切分边界。问题在于：若切分边界恰好落在敏感层（attention 输出投影正是典型高敏感层），该处的 all-reduce 必须在 FP8 或 BF16 域完成，而不能在 FP4 域做——FP4 的 E2M1 尾数在跨卡归约时误差会被放大，且两级缩放的块边界与切分边界不对齐时，归约结果的缩放因子需要重新协商。这意味着通信量与精度域绑定：保精度的代价是 all-reduce 的字节数按 FP8/BF16 计，而非按 4 bit 计。</p>\n<p>规模上去后先崩的往往就是这里。权重省下的显存让你敢开更大的张量并行度，但并行度越高，跨卡归约次数越多，而敏感层边界上的归约又被锁在较高精度域，通信带宽成为新的瓶颈。工程判断是：把高敏感层尽量放在单卡内完成、避免跨切分，或者把张量切分点选在低敏感层上，让 FP4 分支承担更多跨卡流量。这需要与离线层敏感度分析联动——分析结果不只决定哪些层走 FP4，还应决定并行切分的位置。换模型或换分辨率未重跑分析，切分点就可能落在新的 outlier 层上，通信精度域被迫抬高，吞吐随并行度上升反而恶化。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-35\">三十五 · 功耗与尾延迟：批大小与 SLO 的夹缝</h3>\n<p>DiT 的 SLO 以单图端到端时延计，批大小按显存与 SLO 取 1–8。这个区间窄，是因为扩散采样的时延对 batch 极其敏感：batch 增大提升吞吐，但单图时延随 batch 线性劣化，尾延迟（P99）在 batch 接近上限时抬升最快。NVFP4 在这里的作用是双向的——它把主体 GEMM 时延砍半、显存降到 1/4，理论上允许更大 batch 或更高分辨率，但敏感层的 FP8 分支不享受这份红利，成为 batch 放大后最先饱和的部分。功耗侧同理：FP4 Tensor Core 的单位算力能效更高，可敏感层仍跑 FP8，整卡功耗曲线由两条路径叠加，单纯按 FP4 能效估算整机功耗会偏低。</p>\n<p>尾延迟的真正来源是分支切换的抖动。同一 batch 内不同样本走相同的层序列，分支是静态的，但融合 kernel 未到位时，FP4 与 FP8 队列的交替会在时间线上留下空隙，这些空隙在均值上被摊薄、在 P99 上被放大。规模上去后，尾延迟先于均值吞吐崩掉：均值看着达标，P99 已经越过 SLO。可控的做法是把 batch 上限压在敏感层激活峰值允许的范围内，并用融合 kernel 消除队列切换空隙，而不是靠继续加 batch 摊薄固定开销。分辨率提升会同时抬高激活与 attention 中间张量，敏感层占比不变时，显存与尾延迟的压力都落在 FP8 分支上，这是混合精度方案在规模扩张时最需要预判的一条曲线。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-36\">三十六 · 规模上限：敏感层比例与碎片化的双重约束</h3>\n<p>把前四节的代价合起来看，NVFP4 混合精度的规模上限由两个比例决定：敏感层占比与分支切换频度。敏感层占比越高，FP4 收益被 FP8 分支稀释得越彻底，端到端时延趋近纯 FP8 方案，而工程链路却背着离线校准与融合 kernel 的额外成本；分支切换越频繁，调度碎片化越严重，理论 2 倍吞吐的实际兑现率越低。两者叠加时，扩大规模不会线性放大收益，反而在某个点上收益被成本吃掉。这就是“规模上去以后哪里先崩”的答案：先崩的是尾延迟与通信，再崩的是吞吐兑现率，显存反而是最晚触顶的一项。</p>\n<p>量化收益的粗算可以写成 <span class=\"formula\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</span>，其中 <span class=\"formula\">$$\\alpha_{\\text{fp4}}$$</span> 是走 FP4 的算力占比、<span class=\"formula\">$$\\alpha_{\\text{fp8}}$$</span> 是走 FP8 的占比。这个式子说明：FP4 占比不到一半时，整体加速被 FP8 分支的 0.5 系数拖住，接近 1 倍出头；只有把主体 GEMM 尽量划进 FP4、把敏感层压到最小必要集合，加速才逼近 2 倍。工程判断因此落在校准环节：离线分析各层激活的 kurtosis 与 max/mean 比，标记高敏感层时要用“最小必要”原则而非“宁多勿少”，因为每多保一层 FP8，<span class=\"formula\">$$\\alpha_{\\text{fp8}}$$</span> 就抬高一档。换模型或换分辨率必须重跑这套分析，否则被误判的低敏感层会在分布外提示上放大误差，结构崩坏的代价远高于省下的那点显存。</p>\n<p>最后落在部署形态上：VAE 解码前必须统一回 BF16，这一步不是精度洁癖，而是解码器输入精度断层的硬约束——FP4/FP8 分支的汇合结果若直接喂给解码器，色彩漂移与细节丢失会以肉眼可见的方式暴露，且无法靠调 batch 或调并行度补救。把这条边界守住，再让融合 kernel 承担分派与反量化的调度开销，NVFP4 混合精度在 Blackwell 上的系统代价才落在可控区间：显存与主体 GEMM 时延是确定的收益，通信与尾延迟是需要用切分位置和 batch 上限去换的代价。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-37\">三十七 · 混合精度 DiT 的规模边界：先崩在调度，再崩在显存</h3>\n<p>把主体 GEMM 压到 NVFP4、只把 timestep MLP 与 attention 输出投影留在 FP8，理论收益是干净的：主体 GEMM 时延再降一半，权重显存降到 BF16 的 1/4，于是同一张卡能塞下更大的 latent batch 或更高分辨率。但这条收益曲线在规模上去之后不是线性的，因为混合精度把一个原本同构的 GEMM 流拆成了两条队列。FP4 分支要读 block scale、做反量化再进 BF16 残差，FP8 分支走另一套 MMA 路径，两者在层间交替出现。单卡上这种交替的代价是 kernel 启动与流水切换的固定开销被摊薄得不够；一旦 batch 从 1 抬到 4–8，单步前向的层数不变而每层的 tile 数变多，切换次数不变、单次切换的相对成本下降，吞吐才逐渐逼近理论值——这正是“小 batch 看不出收益、大 batch 才兑现”的典型形态。若没有手写融合 kernel 把相邻的 FP4/FP8 段合并进一个 persistent 调度，碎片化会让实际吞吐远低于 <span class=\"formula-inline\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</span> 给出的上界，其中 $\\alpha_{\\text{fp4}}$ 是走 FP4 的 GEMM 时间占比。敏感层比例越高，$\\alpha_{\\text{fp4}}$ 越小，收益越接近纯 FP8 方案，混合精度的工程成本却照付。</p>\n<p>显存这一侧先崩的不是权重而是中间激活缓存。权重按 1/4 压缩后，单步前向的峰值占用转移到 attention 的中间激活与 VAE 解码前的特征图上；低精度让这部分可以容纳更大 batch 或更高分辨率，但 batch 与分辨率是乘性放大的：分辨率翻倍使 token 数约翻四倍，attention 的激活随 token 数超线性增长，而 FP4 只线性压缩了线性层权重。于是容量规划出现一个拐点——权重省下的显存被激活吃掉，SLO 以单图端到端时延计时，尾延迟由最慢的那张图决定，batch 内不同 latent 的层分派完全一致，尾延迟主要来自 FP8 敏感层的串行段而非 FP4 段。用一张小表看各资源的压缩比与瓶颈位置：</p>\n<table class=\"mini\"><thead><tr><th>资源</th><th>相对 BF16 的变化</th><th>规模上去后的瓶颈表现</th></tr></thead><tbody><tr><td>主体 GEMM 权重</td><td>1/4</td><td>不再是限制项</td></tr><tr><td>主体 GEMM 时延</td><td>FP8 的 1/2</td><td>受 kernel 碎片化侵蚀</td></tr><tr><td>中间激活缓存</td><td>随精度下降而下降</td><td>分辨率翻倍时反超权重成为峰值</td></tr><tr><td>FP8 敏感层</td><td>不变</td><td>尾延迟的串行决定项</td></tr></tbody></table>\n<p>通信与功耗在多卡张量并行下才显形。大模型走张量并行时，每个 GEMM 后要 all-reduce，混合精度意味着 FP4 分支的反量化必须在集合通信之前完成、汇合到 BF16 残差再通信，否则跨卡的两级 block scale 无法对齐；这使通信量与 BF16 方案持平，FP4 省下的带宽红利在通信段被抵消。功耗上，FP4 Tensor Core 的单位算力能效更高，但反量化与 block scale 读取是额外的访存与 ALU 开销，在 GEMM 已被压到很短时，这部分开销占单步能耗的比例上升。真正决定规模上限的是敏感层比例：离线校准集给出的 kurtosis 与 max/mean 比标记一旦换模型或换分辨率就必须重跑，分布外提示还可能让被判低敏感的层误差放大，此时 FP4 分支的结构崩坏不会以数值溢出的形式报错，而是以 FID 退化 1–2 个点以上的形式静默出现。工程判断因此落在两处：VAE 解码前必须统一回 BF16，否则解码器输入精度断层直接表现为色彩漂移；以及把融合 kernel 的覆盖范围当作一等指标来验收，而不是只看单层 GEMM 的微基准。</p>\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-38\">三十八 · 精度崩坏的三种指纹与定位手段</h3>\n<p>混合精度推理的精度失败不会以“整体变差”的形式出现，而是以三种可区分的指纹出现，诊断的第一步是分清它们。第一种是<strong>结构崩坏</strong>：图像出现重复纹理、肢体粘连、全局布局错乱，这类现象几乎总是指向 timestep embedding 路径被压到 NVFP4——扩散模型的时间条件一旦失真，去噪轨迹整体偏移，采样器再怎么调也救不回来。第二种是<strong>色彩漂移与高频细节丢失</strong>：图像结构正确但色偏、边缘发糊，这指向 VAE 解码前未统一回 BF16，解码器输入存在精度断层。第三种是<strong>局部异常通道</strong>：画面大体正常，个别区域出现过饱和斑块或棋盘格，这通常是某个被判为低敏感的 attention 输出投影在分布外输入上激活 outlier 放大。</p>\n<p>定位手段不靠肉眼比对，而靠逐层残差探针。做法是在 FP4 分支反量化汇合处与 FP8 分支输出处同时挂 BF16 钩子，对同一 latent 计算两条路径的相对误差：</p>\n<div class=\"formula\">$$\\text{rel}_{\\ell}=\\frac{\\lVert y^{\\text{fp4}}_{\\ell}-y^{\\text{ref}}_{\\ell}\\rVert_2}{\\lVert y^{\\text{ref}}_{\\ell}\\rVert_2},\\qquad \\text{flag}_{\\ell}=\\mathbb{1}\\left[\\text{rel}_{\\ell}&gt;\\tau\\right]$$</div>\n<p>其中 $y^{\\text{ref}}_{\\ell}$ 用 BF16 全精度前向取得，$\\tau$ 按层类型分档设定。工程上不必每步都跑参考路径，只在采样前若干步与最后几步抽样即可，因为扩散轨迹对早期步的误差最敏感。代价是诊断期单图时延翻倍（多一条 BF16 参考路径），显存多出一份中间激活；因此这套探针只应作为发布前的门禁与线上告警时的按需开关，而不是常驻路径。一个具体例子：换分辨率后未重跑敏感度分析，原本被判低敏感的 attention 输出投影在新分辨率下 max/mean 比抬升，探针在该层报出 rel 超阈，直接锁定问题层而不必回退整网。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-39\">三十九 · OOM 的三条来源与显存核算</h3>\n<p>NVFP4 把权重显存压到 BF16 的 1/4，但 OOM 依然会发生，因为权重只是显存账单的一项。三条来源需要分开核算：其一，<strong>中间激活缓存</strong>——低精度后显存下降使 batch 可以开大或分辨率可以提高，一旦调度器按“显存变多了”的直觉放大 batch，激活增长会迅速吃掉权重省下的空间；其二，<strong>双分支并存</strong>——FP4 与 FP8 分支在同一层组内混跑时，若融合 kernel 未实现，两条队列的中间缓冲同时驻留，峰值显存高于任一单分支；其三，<strong>诊断与回滚路径</strong>——BF16 参考路径、全精度回退开关、逐层探针钩子都会额外占用显存，这些“安全设施”本身是 OOM 的隐性贡献者。</p>\n<p>核算应按峰值而非均值做预算：</p>\n<div class=\"formula\">$$M_{\\text{peak}}\\approx M_{w}^{\\text{fp4}}+M_{w}^{\\text{fp8}}+B\\cdot\\left(M_{\\text{act}}+M_{\\text{kv}}\\right)+M_{\\text{diag}}$$</div>\n<p>其中 $B$ 为批大小，$M_{\\text{kv}}$ 指中间激活缓存（此语境下 KV 即扩散中间激活缓存，非自回归 KV cache）。工程判断是：把 $M_{\\text{diag}}$ 显式计入容量规划并预留固定额度，而不是让它在告警时动态挤占；批大小按 SLO 与显存取 1–8 的区间上限应由这条峰值公式反解，而不是试错。代价体现在吞吐上：为压峰值而缩小 batch 会直接损失单卡吞吐，因此更优的做法是把高分辨率请求与低分辨率请求分流到不同实例规格，而不是在同一实例上动态伸缩 batch。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-40\">四十 · 批抖动与路由不均：调度层的两类病</h3>\n<p>批抖动指同一实例上批大小在相邻调度周期之间大幅震荡，表现为 GPU 利用率锯齿与端到端时延方差抬升。根因通常不在 GPU 而在上游：请求到达是泊松式的，而 DiT 单步前向的时延对批大小并非线性，调度器若按“攒够即发”策略，会在攒批等待与突发清空之间来回摆动。诊断看两个量：批大小的时间序列方差，以及每批的实际计算时间与批大小的相关系数；后者若明显偏离线性，说明存在分辨率混杂或分支比例变化导致的 kernel 切换开销。</p>\n<p>路由不均则是混合精度特有的病：FP4 与 FP8 分支的层数比例在不同请求间不一致（例如不同分辨率触发不同的敏感层集合），导致同一批内 kernel 调度碎片化。表现为理论吞吐与实际吞吐的差距随批内分辨率混杂度上升而扩大。可用事实给出的机制解释是：FP4 与 FP8 分支混跑本身造成调度碎片化，需手写融合 kernel 才能兑现理论吞吐；未融合时实际吞吐远低于理论值。诊断手段是统计每个调度周期内 FP4 GEMM 与 FP8 GEMM 的启动次数与占用时长之比，若该比值随批内请求构成剧烈波动，说明路由不均已成主要瓶颈。</p>\n<p>缓解不是调调度参数，而是约束输入构成：把同分辨率、同分支比例的请求聚到同一批，用分辨率分桶替代动态攒批；对必须混杂的批，宁可拆小也不让分支比例在批内漂移。代价是队列等待时间上升、尾延迟分布变宽，这与吞吐收益构成直接权衡，需按 SLO 以单图端到端时延为准做取舍。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-41\">四十一 · 尾延迟尖刺的四个来源</h3>\n<p>尾延迟（P99）在扩散服务里比均值更能决定 SLO 达标率，因为单图端到端时延是用户可感知量。尖刺有四个来源，需分别设监控点。第一，<strong>首次请求的冷路径</strong>：层敏感度标签表、block scale 表、融合 kernel 的首次加载与 JIT 编译都发生在第一批请求上，表现为启动后若干请求的时延显著高于稳态。第二，<strong>分支切换</strong>：批内请求构成变化触发 FP4/FP8 队列重排，切换开销一次性计入该批。第三，<strong>显存压力下的重算或换出</strong>：当峰值显存逼近上限，激活缓存被驱逐后需重算，这一开销在尾部分布上体现为长尾。第四，<strong>回滚触发</strong>：精度告警触发整网回退到 FP8/BF16 时，该实例上的在途请求时延陡增。</p>\n<p>监控应按请求打标签而非按实例聚合：把每个请求的分支比例、分辨率、是否命中诊断探针、是否经历回滚作为维度，分别统计 P50/P99。工程判断是：尾延迟尖刺若集中在冷路径，用预热请求解决，代价是启动期占用算力；若集中在分支切换，用分桶调度解决；若集中在显存驱逐，说明批大小上限设得过高，应下调而非加显存。公式上可把端到端时延分解为</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=\\sum_{t=1}^{N_{\\text{step}}}\\left(T^{\\text{fp4}}_{t}+T^{\\text{fp8}}_{t}+T^{\\text{switch}}_{t}\\right)+T_{\\text{vae}}$$</div>\n<p>逐项打点即可把尖刺归因到具体项，而不是笼统地归为“GPU 慢”。一个具体例子：某实例 P99 抬升但 P50 不变，分解后发现 $T_{\\text{switch}}$ 在少数批上异常，追查为批内混入高分辨率请求改变了敏感层集合，按分辨率分桶后尖刺消失。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-42\">四十二 · 监控指标体系与告警阈值设计</h3>\n<p>监控要覆盖精度、显存、调度、时延四层，且每层至少一个能直接触发回滚的量。精度层：逐层相对误差探针的抽样统计、输出图像的分布漂移指标（如通道均值与方差的偏移）、VAE 输入是否确为 BF16 的断言。显存层：峰值显存占上限的比例、激活缓存驱逐次数、诊断路径占用额度。调度层：批大小方差、FP4/FP8 kernel 启动次数比、批内分辨率混杂度。时延层：按标签分组的 P50/P99、时延分解各项占比。</p>\n<p>阈值设计的原则是“宁可误报不可漏报”，因为精度崩坏一旦流出到用户侧不可逆，而误报的代价只是一次回滚。具体做法是双阈值：软阈值触发抽样加密与告警，硬阈值触发自动回滚。软硬阈值之间留出观察窗口，让值班工程师有机会在回滚前确认是否为分布外请求导致的假阳性——可用事实明确指出，分布外提示可能让被判低敏感层误差放大，这类假阳性在换模型或换分辨率初期尤其常见。</p>\n<table class=\"mini\"><thead><tr><th>层</th><th>监控量</th><th>触发动作</th></tr></thead><tbody><tr><td>精度</td><td>逐层 rel 抽样、VAE 输入精度断言</td><td>软阈值加密探针；硬阈值整网回退</td></tr><tr><td>显存</td><td>峰值占比、驱逐次数</td><td>下调批上限、关闭诊断路径</td></tr><tr><td>调度</td><td>批方差、分支启动比</td><td>切分桶策略、拆批</td></tr><tr><td>时延</td><td>分组 P99、分解项占比</td><td>定位尖刺来源后定点修复</td></tr></tbody></table>\n<p>代价是监控本身消耗算力与显存：常驻探针会让稳态吞吐下降，因此探针应抽样而非全量，且抽样率随软阈值状态动态调整。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-43\">四十三 · 回滚路径的分级与切换成本</h3>\n<p>回滚不是二值的“开/关”，而应分级。第一级是<strong>层级回退</strong>：把告警层从 NVFP4 切回 FP8，其余层不动，代价最小，适用于单层 outlier 放大。第二级是<strong>分支比例回退</strong>：把敏感层集合整体扩大，牺牲部分 FP4 收益换取稳定，适用于换分辨率后敏感度标签整体失准。第三级是<strong>整网回退</strong>：全部回到 FP8 或 BF16，适用于结构崩坏已发生且无法定位到具体层。第四级是<strong>流量回退</strong>：把请求切到未启用量化的备用实例，适用于回滚本身也来不及的紧急情况。</p>\n<p>分级回滚的关键是切换成本可预算。层级回退只需替换层标签表并让调度器在下一批生效，切换开销接近零但会引入批内分支比例突变，进而触发前述路由不均；整网回退需要重新加载权重与 block scale 表，切换期间在途请求时延陡增，因此必须配合流量排空。工程判断是：把层标签表做成可热更新的配置而非编译期常量，让第一级回滚成为默认动作；整网回退只作为兜底，且必须演练过排空流程。回滚后不应立即恢复 FP4，而应让探针在回滚态下继续采样，确认分布外请求是否已退出，否则会在同一批请求上反复回滚——这是混合精度服务最常见的运维陷阱。</p>\n<p>最后落在具体机制上：回滚状态的判定不应由单一指标决定，而应由“探针 rel 超阈的层数”与“输出分布漂移是否可归因于分布外输入”两个信号联合判定；前者给出定位，后者给出是否值得等待。把这两个信号写进告警规则，比任何单一阈值都更能避免在精度与吞吐之间反复横跳。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-44\">四十四 · 失效边界：从“能跑”到“崩坏”只差一次误判</h3>\n<p>这套分层混合精度的收益完全建立在“敏感层判对了”这一前提上，而判据是离线校准集上统计的 kurtosis 与 max/mean 比。一旦推理时的 latent 分布偏离校准集——换分辨率、换采样步数、换 prompt 结构——被判为低敏感的层可能瞬间出现激活 outlier 放大，此时 E2M1 的动态范围被两级缩放 <span class=\"formula\">$$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}}$$</span> 拉回可用区间的前提失效，误差沿残差链累积，表现为结构崩坏而非渐进退化。诊断上不能只看端到端 FID：要按层记录 FP4 分支反量化后的激活 max/rms 比，与离线基线比对，偏离阈值即触发该层回退 FP8。回滚粒度必须是层级的，整模型回退 BF16 会一次性丢掉全部显存与吞吐收益。</p>\n<p>第二类失败是调度碎片化。FP4 与 FP8 GEMM 交替入队，若没有手写融合 kernel，每次分支切换都带来 launch 与同步开销，实际吞吐远低于 <span class=\"formula\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</span> 给出的理论上界——其中 <span class=\"formula\">$$\\alpha_{\\text{fp4}}$$</span> 为走 NVFP4 的 GEMM 占比。敏感层比例越高，<span class=\"formula\">$$\\alpha_{\\text{fp4}}$$</span> 越低，收益被碎片化吞掉得越快，这正是规模上限受 outlier 层比例约束的机制来源。监控应采集每层 GEMM 的实际耗时占比与队列空转率，而不是只看 GPU 利用率。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>根因</th><th>处置</th></tr></thead><tbody><tr><td>结构崩坏、色彩漂移</td><td>VAE 解码前未统一回 BF16，解码器输入精度断层</td><td>解码入口强制 BF16 cast，作为不可绕过的边界</td></tr><tr><td>吞吐低于理论值</td><td>FP4/FP8 分支未融合，kernel 调度碎片化</td><td>融合 kernel 或按层重排执行顺序聚合同精度分支</td></tr><tr><td>OOM 与批抖动</td><td>低精度省下的显存被更大 batch 吃掉，激活缓存峰值未预留</td><td>按峰值而非均值定 batch，保留回退余量</td></tr></tbody></table>\n<p>批抖动与尾延迟尖刺在 DiT 单步前向里尤其隐蔽：批大小按显存与 SLO 取 1–8，低精度后显存降至 BF16 的 1/4，运维自然会推高 batch 或分辨率，但中间激活缓存的峰值增长是非线性的，一旦越界就触发重分配与重试，表现为周期性尖刺而非稳定 OOM。容量规划要按 P99 激活峰值留出回退到 FP8 的显存余量，否则回滚动作本身就会 OOM。工程判断很直接：把层敏感度重跑、融合 kernel 覆盖率、BF16 解码边界三项做成上线前的硬门槛，任何一项缺失，这套方案的收益都不足以抵消其失效代价。</p>\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-45\">四十五 · 对照轴：把“选哪个”拆成四个可判定的维度</h3>\n<p>同族算法之间的选择不能靠“哪个更先进”，而要靠四个能在部署前回答的维度：<strong>精度档位与 outlier 隔离方式</strong>、<strong>硬件路径的专用程度</strong>、<strong>离线工程链路的长度</strong>、<strong>kernel 调度碎片化的代价</strong>。DiT NVFP4 混合精度的定位是：精度档位只有 E2M1 与 FP8 两档，靠两级 micro-block scaling 把 E2M1 的动态范围拉回可用区间，并用层标签把 outlier 层隔离到 FP8/BF16 分支；硬件路径专指 Blackwell 原生 FP4 Tensor Core 与 block scale 硬件路径；离线链路包含层敏感度分析（kurtosis 与 max/mean 比）与融合 kernel 手写；碎片化代价来自 FP4 与 FP8 两条 GEMM 队列混跑。任何一次选型，本质是把这四个维度与自己的服务形态对齐，而不是比较峰值吞吐。</p>\n<p>量化误差的放大由激活分布形状决定，这是判断“能不能压到 FP4”的第一性依据：</p>\n<div class=\"formula\">$$\\text{err}_{\\ell} \\propto \\frac{\\max|a_\\ell|}{\\text{rms}(a_\\ell)}$$</div>\n<p>该比值越大，块级缩放越难把整块拉进 E2M1 的表示范围，该层就越应留在 FP8。层敏感度分析做的就是把这个比值与 kurtosis 一起算出，给每层打标签。注意这是离线量：换模型、换分辨率都要重跑，因此它直接进入选型的“工程链路长度”维度。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-46\">四十六 · 决策表：五种候选与适用条件</h3>\n<p>把同族候选放在一张表里，判据写成可观测条件而非偏好。表中“主体 GEMM 时延”以 BF16 为基准做相对表述，不引入未给出的绝对数字。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>候选</th><th>精度档位</th><th>outlier 处理</th><th>主体 GEMM 时延</th><th>显存</th><th>适用条件</th><th>不适用</th></tr>\n</thead>\n<tbody>\n<tr><td>BF16 基线</td><td>单档</td><td>无需</td><td>基准</td><td>基准</td><td>校准集缺失、分辨率频繁切换、SLO 宽松</td><td>显存紧张、GEMM 占主导</td></tr>\n<tr><td>DiT FP8 注意力与 GEMM</td><td>单档 FP8</td><td>靠 E4M3 动态范围吸收</td><td>低于 BF16</td><td>低于 BF16</td><td>outlier 未极端、链路短优先、快速上线</td><td>显存极紧、需再压一半时延</td></tr>\n<tr><td>DiT MX 混合精度分块</td><td>多档（分块共享指数）</td><td>块内共享 scale</td><td>低于 BF16</td><td>低于 BF16</td><td>需要细粒度块划分、跨精度档位灵活切换</td><td>追求硬件路径专用与最少档位</td></tr>\n<tr><td>DiT 分块 PTQ 校准</td><td>随目标精度</td><td>依赖校准质量</td><td>取决于所压精度</td><td>取决于所压精度</td><td>已有成熟校准流水、模型版本稳定</td><td>分布外提示频繁</td></tr>\n<tr><td>NVFP4 混合精度（本条）</td><td>两档（E2M1 + FP8）</td><td>层标签隔离敏感层</td><td>主体 GEMM 再降一半</td><td>降至 BF16 的 1/4</td><td>显存紧张、GEMM 占主导、能承担离线校准与 kernel 调优</td><td>敏感层比例高、无融合 kernel 投入</td></tr>\n</tbody>\n</table>\n<p>读表方式：先看“显存”列是否构成硬约束，再看“主体 GEMM 时延”是否是端到端瓶颈。若两者都不成立，选 BF16 或 FP8 即可，NVFP4 的离线链路与碎片化代价换不来收益。若显存是硬约束而 GEMM 不是瓶颈，NVFP4 的 1/4 显存收益仍可单独成立——此时它换来的是更大 batch 或更高分辨率，而不是时延。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-47\">四十七 · 收益上界的算术：什么时候 NVFP4 值得选</h3>\n<p>混合精度的端到端加速由 FP4 覆盖的算子比例决定，不能按“FP4 吞吐是 FP8 的 2 倍”直接外推。设 α_fp4 为走 NVFP4 分支的 GEMM 时间占比（以 FP8 为基准），剩余部分留在 FP8，则一个可用的上界估计是：</p>\n<div class=\"formula\">$$\\text{Speedup} \\approx \\frac{1}{\\alpha_{\\text{fp4}} + (1-\\alpha_{\\text{fp8}})\\cdot 0.5}$$</div>\n<p>该式的含义是：只有被 FP4 覆盖的那部分拿到 2 倍，未被覆盖的部分按 FP8 的相对代价计入。它给出的工程判断很直接——敏感层越多，α_fp4 越小，加速越趋近于 1，此时 NVFP4 只剩显存收益。因此选型前应先估算敏感层比例：timestep MLP 与 attention 输出投影是已知的高敏感候选，若模型结构中这两类层占比高，NVFP4 的时延收益会被显著压缩，应退回 FP8 方案或只对非敏感的大矩阵层启用 FP4。</p>\n<p>显存侧的账更干净：权重与中间激活降到 BF16 的 1/4，KV（此处指中间激活缓存）低精度后显存大幅下降，可容纳更大 batch 或更高分辨率。对单图端到端时延为 SLO 的服务，batch 取 1–8，显存收益往往先于时延收益兑现——这也是 NVFP4 在显存紧张场景下即便加速有限仍值得选的原因。</p>\n<p>具体例子：一个以 attention 输出投影与 timestep MLP 为主要参数量的 DiT，若这两类层被判为高敏感而全部留在 FP8，则 α_fp4 只覆盖剩余线性层，端到端加速远低于 2 倍，但显存仍按 1/4 兑现；反之，若敏感层仅占少数、主体是宽线性层，α_fp4 接近 1，时延收益才接近理论上界。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-48\">四十八 · 与 MX 及 FP8 的分界：精度档位数量决定调优成本</h3>\n<p>与 DiT MX 混合精度分块相比，NVFP4 的差别不在“更省”，而在档位更少、硬件路径更专。MX 用分块共享指数，档位划分更灵活，适合需要细粒度块策略的场景；NVFP4 用 E2M1 加两级 micro-block scaling，缩放结构为：</p>\n<div class=\"formula\">$$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}},\\qquad \\hat{w}_i\\in\\text{E2M1}$$</div>\n<p>两级缩放把 E2M1 的动态范围拉回可用区间，代价是调优自由度下降：块大小与张量级 scale 的取值空间比 MX 窄，精度档位只有两档，一旦敏感层判定失误，没有中间档位可以兜底。因此 NVFP4 的调优更依赖融合 kernel——FP4 与 FP8 分支混跑导致 kernel 调度碎片化，只有手写融合 kernel 才能兑现理论吞吐；若团队没有 kernel 投入，实际吞吐会远低于理论值，此时选 MX 或纯 FP8 更稳妥。</p>\n<p>与 DiT FP8 注意力与 GEMM 的分界则更简单：FP8 是单档方案，链路短、无需层敏感度分析，outlier 靠 E4M3 的动态范围吸收；NVFP4 把主体 GEMM 再降一半时延、显存降至 1/4，但必须做分层隔离。判断点是 outlier 是否已经极端到 E4M3 无法吸收——若 FP8 下已出现结构崩坏或明显退化，才需要引入 NVFP4 的层标签机制；若 FP8 已满足 SLO，引入 NVFP4 只是增加工程链路与碎片化风险。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-49\">四十九 · 适用条件清单与规模上限</h3>\n<ul>\n<li><strong>选 NVFP4 混合精度的条件</strong>：显存构成硬约束；主体 GEMM 占端到端时延主导；有稳定校准集且模型/分辨率版本可控；团队能承担融合 kernel 手写与调度调优。</li>\n<li><strong>退回 FP8 的条件</strong>：outlier 未极端、FP8 已满足 SLO；模型或分辨率频繁切换导致层敏感度分析无法复用；无 kernel 调优资源。</li>\n<li><strong>退回 BF16 的条件</strong>：校准集缺失、分布外提示占比高，任何低精度都可能让被判低敏感层误差放大；SLO 宽松、显存不紧。</li>\n<li><strong>考虑 MX 分块的条件</strong>：需要更细的块级策略与更多精度档位，且不追求 Blackwell 专用 FP4 路径的最短时延。</li>\n<li><strong>考虑分块 PTQ 校准的条件</strong>：已有成熟校准流水、模型版本稳定，量化目标精度不限于 FP4。</li>\n</ul>\n<p>规模上限受两个量约束：outlier 层比例与 kernel 碎片化程度。敏感层越多，FP4 收益越小；分支越多、调度越碎，理论吞吐越难兑现。工程上应把“敏感层占比”作为选型的第一道闸门——它同时决定时延收益的上界与碎片化的严重程度，是唯一一个在离线阶段就能定量回答、且直接决定是否值得投入融合 kernel 的指标。</p>\n<p>最后落在具体机制上：层敏感度分析产出的层标签，不只是推理时的分派依据，也是选型决策的输入——把标签统计成敏感层比例，代入收益上界公式，若加速上界不足以覆盖融合 kernel 的工程成本，就应停在 FP8；若显存收益单独成立而时延收益有限，则 NVFP4 仍可作为显存方案启用，但需接受碎片化带来的实际吞吐折损，并把 VAE 解码前统一回 BF16 作为不可省略的收尾约束。</p>\n\n<h3 id=\"alg-nvfp4-hybrid-dit-sec-50\">五十 · 与 FP8、MX 两条相邻路线的分岔口：何时值得为 NVFP4 付融合 kernel 的账</h3>\n<p>把 NVFP4 混合精度放进同族算法谱系里看，它并不是 FP8 的简单升级，而是拿“离线分层 + 手写融合 kernel”换“主体 GEMM 再降一半时延、显存降到 BF16 的 1/4”。与 DiT FP8 注意力与 GEMM 方案相比，后者不需要层敏感度分析、不需要 FP4/FP8 双队列调度，工程链路短、分布外提示下行为可预测，代价是显存与 GEMM 时延都停在 FP8 档位。与 MX 混合精度相比，NVFP4 用 E2M1 加两级 micro-block scaling（$w_i=\\hat{w}_i\\cdot s_{\\text{block}}\\cdot s_{\\text{tensor}}$），精度档位更少、硬件路径更专——Blackwell 原生 FP4 Tensor Core 与 block scale 走同一条硬件通路——但调优更依赖融合 kernel，MX 那套更通用的缩放语义在 NVFP4 上换不来等价的吞吐。三者的分岔不在精度上限，而在“敏感层比例”与“kernel 碎片化容忍度”这两个可测的工程量。</p>\n<p>决策的第一道闸门是敏感层占比。设高敏感层（timestep MLP、attention 输出投影这类 max/rms 比与 kurtosis 显著偏高的层）的 FLOPs 占比为 $\\alpha_{\\text{fp4}}$ 的反面，即保 FP8 的比例 $\\beta$，则理论加速近似为 $\\text{Speedup}\\approx\\frac{1}{(1-\\beta)\\cdot 0.5+\\beta}$：全部走 FP4 时上限为 2 倍，$\\beta$ 每上升一档收益线性衰减。当 $\\beta$ 超过约三分之一，NVFP4 相对纯 FP8 的净收益已不足以覆盖离线校准与 kernel 调优的固定成本，此时应直接选 FP8。第二道闸门是部署形态：单卡、批大小 1–8、SLO 以单图端到端时延计的服务化场景，显存压力真实存在（低精度后中间激活缓存下降可容纳更大 batch 或更高分辨率），NVFP4 的显存收益能兑现；而研究性、频繁换模型换分辨率的场景，每次都要重跑敏感度分析，链路成本会吃掉收益。</p>\n<p>失效条件必须写进选型表而不是脚注。其一，FP4 与 FP8 分支混跑天然产生 kernel 调度碎片化，若不手写融合 kernel，实际吞吐远低于理论值——这是 NVFP4 路线最常见的“账面上 2 倍、实测不如 FP8”的成因。其二，敏感度分析依赖离线校准集，分布外提示可能让被判低敏感层误差放大，因此校准集必须覆盖目标分辨率与提示分布，换模型或换分辨率未重跑会直接把 outlier 层误压到 NVFP4，导致结构崩坏。其三，VAE 解码前未统一回 BF16 会造成解码器输入精度断层与色彩漂移、细节丢失，这一条与量化档位无关，是数据流末端的硬约束。整体 FID 退化可控在 1–2 个点内，是这条路线在机制证据（paper-hq-dit-efficient-diffusion-transform-2024、paper-fp4dit-towards-effective-floating-po-2025）下的定性结论，而非任意模型任意分辨率都成立的保证。</p>\n<table class=\"mini\"><thead><tr><th>选型条件</th><th>NVFP4 分层混合</th><th>DiT FP8</th><th>MX 混合精度</th></tr></thead><tbody><tr><td>敏感层占比低、主体 GEMM 主导</td><td>首选，收益最大</td><td>次选，链路短</td><td>可用，调优弹性大</td></tr><tr><td>显存紧张、需更大 batch 或更高分辨率</td><td>首选，显存降至 1/4</td><td>受限于 FP8 显存档位</td><td>取决于缩放粒度</td></tr><tr><td>可承担离线校准与融合 kernel 成本</td><td>必要条件</td><td>不需要</td><td>部分需要</td></tr><tr><td>频繁换模型/换分辨率</td><td>不适用，需重跑分析</td><td>适用</td><td>较适用</td></tr><tr><td>分布外提示占比高</td><td>需扩大校准集，否则失效</td><td>行为更可预测</td><td>居中</td></tr></tbody></table>\n<p>工程判断落在最后一步：先用手写融合 kernel 把 FP4 与 FP8 两条 GEMM 队列在 BF16 残差处汇合的路径打通，再拿真实校准集量出 $\\beta$，用上面的 Speedup 公式反推是否越过盈亏线；若 $\\beta$ 偏高或分布外流量占比大，退回 FP8 并把省下的工程预算投到批调度与 KV/中间激活管理上，往往比硬啃 NVFP4 的分层隔离更划算。规模上限由 outlier 层比例与 kernel 碎片化共同约束——敏感层越多，FP4 收益越小，这条曲线决定了 NVFP4 混合精度是“显存与 GEMM 双紧”场景的专用武器，而不是通用默认档。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · 视频与流式生成推理</td></tr><tr><td>解决什么</td><td>DiT 权重与激活在 4bit 下量化误差急剧放大，尤其 timestep embedding 与 attention…</td></tr><tr><td>一句话机制</td><td>对 outlier 敏感的层（timestep MLP、attention 输出投影）保留 FP8/BF16，其余线性…</td></tr><tr><td>代价与失效</td><td>层敏感度分析需离线校准集，换模型/换分辨率要重跑，工程链路长；FP4 与 FP8 分支混跑导致 kernel 调度碎片化，需手写融合 ke…</td></tr><tr><td>后继</td><td>阶段级扩散服务流水</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-nvfp4-hybrid-dit · 共 8 个片段</p>\n";break;}}})();
